import{g as a,ad as n,r as e,A as p}from"./chunks/framework.nEVVyQQB.js";const h=JSON.parse('{"title":"Migration from v0","description":"","frontmatter":{"pageClass":"migration-page"},"headers":[],"relativePath":"docs/migration.md","filePath":"docs/migration.md","lastUpdated":1786213964000}'),t={name:"docs/migration.md"};function o(l,s,c,d,i,r){return n(),e("div",null,[...s[0]||(s[0]=[p(`<h1 id="migration-from-v0" tabindex="-1">Migration from v0 <a class="header-anchor" href="#migration-from-v0" aria-label="Permalink to “Migration from v0”">​</a></h1><p>A guide for moving an existing app onto <code>frappe-ui</code> v1. Work through one component family at a time. Each section opens with a before/after table. For the full change list see the <a href="https://github.com/frappe/frappe-ui/blob/main/v1-release/changelog.md" target="_blank" rel="noreferrer">changelog</a>; for the rationale behind each API see the <a href="https://github.com/frappe/frappe-ui/tree/main/v1-release" target="_blank" rel="noreferrer">v1 release specs</a>.</p><p>After each pass, <code>grep</code> for the old prop or slot name to catch anything missed, then test the flows you touched. Type-checking won&#39;t catch focus, slot renames, or visual regressions.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to “Requirements”">​</a></h2><p>v1 requires <strong>Node <code>&gt;=20.19.0</code></strong> (<code>package.json</code> <code>engines</code>); this is a breaking bump from the 0.1.x line (Node 18).</p><h2 id="dialog" tabindex="-1">Dialog <a class="header-anchor" href="#dialog" aria-label="Permalink to “Dialog”">​</a></h2><p>The <code>options</code> blob is flattened into top-level props. See the <a href="./components/dialog">Dialog</a> component page for the full API.</p><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>v-model=&quot;show&quot;</code></td><td><code>v-model:open=&quot;show&quot;</code></td></tr><tr><td><code>:options=&quot;{ title, size, actions }&quot;</code></td><td><code>title</code> / <code>size</code> / <code>:actions</code></td></tr><tr><td><code>disableOutsideClickToClose</code></td><td><code>:dismissible=&quot;false&quot;</code></td></tr><tr><td><code>&lt;template #body-content&gt;</code></td><td>default slot</td></tr><tr><td><code>&lt;template #body-main&gt;</code></td><td>default slot</td></tr><tr><td><code>&lt;template #body-title&gt;</code></td><td><code>&lt;template #title&gt;</code></td></tr><tr><td><code>&lt;template #body-header&gt;</code></td><td><code>&lt;template #title&gt;</code> (no direct replacement)</td></tr><tr><td><code>&lt;template #body&gt;</code></td><td><code>bare</code> prop + default slot</td></tr><tr><td><code>onClick: (close) =&gt; …</code></td><td><code>onClick: ({ close }) =&gt; …</code></td></tr><tr><td><code>:icon=&quot;{ appearance: &#39;warning&#39; }&quot;</code></td><td><code>:icon=&quot;{ theme: &#39;yellow&#39; }&quot;</code></td></tr><tr><td><code>dialogRef.close()</code></td><td><code>v-model:open</code> / <code>close</code> slot prop</td></tr><tr><td>manual focus hacks / <code>v-focus</code></td><td><code>autofocus</code> attr on a descendant</td></tr></tbody></table><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Dialog</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">options</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">{</span><span class="s_r4oegk"> title</span><span class="s_1jjt6x">: </span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">Edit Item</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> }</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">show</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #body-content&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;FormControl label=&quot;Name&quot; v-model=&quot;item.name&quot; /&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;/template&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #actions&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;Button variant=&quot;solid&quot; @click=&quot;save&quot;&gt;Save&lt;/Button&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;/template&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Dialog</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Dialog</span><span class="s_1i4ay4"> title</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">Edit Item</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">:</span><span class="s_1i4ay4">open</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">show</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;FormControl label=&quot;Name&quot; v-model=&quot;item.name&quot; /&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #actions&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;Button variant=&quot;solid&quot; @click=&quot;save&quot;&gt;Save&lt;/Button&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;/template&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Dialog</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p>For reactive <code>:options</code> objects, spread them: <code>&lt;Dialog v-bind=&quot;opts || {}&quot; /&gt;</code>. For the imperative API, use <code>dialog.confirm</code> / <code>dialog.danger</code> / <code>dialog.prompt</code> from <code>frappe-ui</code> (callback-based: <code>onConfirm</code> resolves to close, throws to stay open) and wrap your app root in <code>&lt;FrappeUIProvider&gt;</code>.</p><h3 id="icon-appearance-→-icon-theme" tabindex="-1"><code>icon.appearance</code> → <code>icon.theme</code> <a class="header-anchor" href="#icon-appearance-→-icon-theme" aria-label="Permalink to “icon.appearance → icon.theme”">​</a></h3><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Dialog</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">icon</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">{</span><span class="s_r4oegk"> name</span><span class="s_1jjt6x">: </span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">lucide-alert-triangle</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">, </span><span class="s_r4oegk">appearance</span><span class="s_1jjt6x">: </span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">warning</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> }</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> ...</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Dialog</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">icon</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">{</span><span class="s_r4oegk"> name</span><span class="s_1jjt6x">: </span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">lucide-alert-triangle</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">, </span><span class="s_r4oegk">theme</span><span class="s_1jjt6x">: </span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">yellow</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> }</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> ...</span><span class="s_1zd9e2"> /&gt;</span></span></code></pre></div><p><code>appearance</code> is dropped silently — Vue accepts the unknown key with no error, so the icon renders with no tone. Map <code>warning → yellow</code>, <code>info → blue</code>, <code>danger → red</code>, <code>success → green</code>.</p><h3 id="a-template-ref-no-longer-exposes-close" tabindex="-1">A template ref no longer exposes <code>close()</code> <a class="header-anchor" href="#a-template-ref-no-longer-exposes-close" aria-label="Permalink to “A template ref no longer exposes close()”">​</a></h3><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Dialog</span><span class="s_1i4ay4"> ref</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">dialogRef</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">show</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_22m8k2">dialogRef</span><span class="s_1jjt6x">.</span><span class="s_11933w">value</span><span class="s_1jjt6x">.</span><span class="s_indoxt">close</span><span class="s_13ahmt">()</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Dialog</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">:</span><span class="s_1i4ay4">open</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">show</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_22m8k2">show</span><span class="s_1jjt6x">.</span><span class="s_11933w">value</span><span class="s_2ekfrt"> =</span><span class="s_40mev6"> false</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p><code>Dialog</code> exposes nothing on its template ref (ADR-0012); calling <code>.close()</code> now throws. Drive <code>open</code> through <code>v-model:open</code>, or use the <code>close</code> slot prop from inside <code>#default</code> / <code>#actions</code>.</p><h2 id="datepicker-timepicker-family" tabindex="-1">DatePicker / TimePicker family <a class="header-anchor" href="#datepicker-timepicker-family" aria-label="Permalink to “DatePicker / TimePicker family”">​</a></h2><p>Covers <code>DatePicker</code>, <code>DateRangePicker</code>, <code>DateTimePicker</code>, and <code>TimePicker</code>. They share the popover-trigger vocabulary. Removed members are deleted, not aliased — a call site that still uses one breaks at the tag rather than warning; <code>grep</code> for each old name after upgrading.</p><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>:value</code> prop</td><td><code>v-model</code></td></tr><tr><td><code>placement=&quot;bottom-start&quot;</code></td><td><code>side</code> + <code>align</code> + <code>offset</code></td></tr><tr><td><code>:autoClose</code></td><td><code>:keepOpen</code> (inverted)</td></tr><tr><td><code>allowCustom</code> / picker-level <code>readonly</code></td><td><code>typeable</code></td></tr><tr><td><code>inputClass</code></td><td><code>class</code></td></tr><tr><td><code>minDate</code>/<code>maxDate</code>/<code>minTime</code>/<code>maxTime</code></td><td><code>min</code> / <code>max</code></td></tr><tr><td><code>#target</code></td><td><code>#trigger</code></td></tr><tr><td><code>TimePicker.scrollMode</code></td><td>nothing — list is always centered</td></tr><tr><td><code>TimePicker</code> template ref <code>.selectAll()</code> / <code>.blurInput()</code></td><td>nothing — dead, no callers</td></tr></tbody></table><p><code>@change</code> still fires alongside <code>@update:modelValue</code> — it wasn&#39;t deprecated and doesn&#39;t need replacing.</p><p>Most of the table above is a <strong>silent break</strong>: an old prop name that&#39;s no longer in the component&#39;s types lands as an inert extra attribute (or, for <code>min</code>/<code>max</code> aliases, the constraint just stops being enforced) instead of throwing. TypeScript callers get a compile error instead. <code>#target</code> is the one slot case — content in a leftover <code>&lt;template #target&gt;</code> silently stops rendering.</p><p>Behavior changes that apply even if you don&#39;t touch your code:</p><ul><li><code>DateRangePicker</code> emits a <code>[from, to]</code> tuple. Update handlers that called <code>.split(&#39;,&#39;)</code> on the value.</li><li><code>DateTimePicker</code> no longer auto-closes on date click. Close from <code>@update:modelValue</code> or add an <code>#actions</code> Apply button.</li><li>The popover footer and auto Clear button were removed. Render an explicit Clear inside <code>#actions</code> if you relied on it.</li><li><code>DateRangePicker.clearable</code> now defaults to <code>true</code>. Pass <code>:clearable=&quot;false&quot;</code> to opt out.</li><li><code>useDatePicker</code> and its helpers (<code>getDate</code>, <code>getDatesAfter</code>, <code>getDaysInMonth</code>, <code>isLeapYear</code>) are deleted — the import fails. Nothing in the picker components used them; drop the import.</li></ul><h2 id="monthpicker" tabindex="-1">MonthPicker <a class="header-anchor" href="#monthpicker" aria-label="Permalink to “MonthPicker”">​</a></h2><p><code>MonthPicker</code> is deleted — the import fails. Use <code>Select</code> with month options:</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">MonthPicker</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">month</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Select</span></span>
<span class="line"><span class="s_1i4ay4">  v-model</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">month</span><span class="s_w1p9wo">&quot;</span></span>
<span class="line"><span class="s_1jjt6x">  :</span><span class="s_1i4ay4">options</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">[</span></span>
<span class="line"><span class="s_13ahmt">    {</span><span class="s_r4oegk"> label</span><span class="s_1jjt6x">: </span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">January</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">, </span><span class="s_r4oegk">value</span><span class="s_1jjt6x">: </span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">01</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">    {</span><span class="s_r4oegk"> label</span><span class="s_1jjt6x">: </span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">February</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">, </span><span class="s_r4oegk">value</span><span class="s_1jjt6x">: </span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">02</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_1th9sy">    // ...</span></span>
<span class="line"><span class="s_13ahmt">  ]</span><span class="s_w1p9wo">&quot;</span></span>
<span class="line"><span class="s_6am9cx">/&gt;</span></span></code></pre></div><h2 id="selection-family-dropdown-select-combobox-multiselect" tabindex="-1">Selection family (Dropdown / Select / Combobox / MultiSelect) <a class="header-anchor" href="#selection-family-dropdown-select-combobox-multiselect" aria-label="Permalink to “Selection family (Dropdown / Select / Combobox / MultiSelect)”">​</a></h2><p>Upgrade all three pickers together. They share an option shape and a slot vocabulary, and most apps use more than one.</p><p>Removed members are deleted, not aliased — a call site that still uses one breaks at the tag rather than warning.</p><h3 id="shared" tabindex="-1">Shared <a class="header-anchor" href="#shared" aria-label="Permalink to “Shared”">​</a></h3><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td>Dropdown <code>{ group, items }</code></td><td><code>{ group, options }</code></td></tr><tr><td><code>#option</code> slot</td><td><code>#item-label</code>, plus <code>#item-prefix</code> for icons</td></tr><tr><td><code>option</code> item slot prop</td><td><code>item</code></td></tr><tr><td><code>clearSelection</code> / <code>clearAll</code> slot prop</td><td><code>clear</code></td></tr><tr><td>chevron / trailing content</td><td><code>#suffix</code> slot (replaces the chevron)</td></tr></tbody></table><p>Option values are <code>string | number</code> everywhere. <code>Select</code> no longer accepts <code>bigint</code> or object values.</p><h3 id="select" tabindex="-1">Select <a class="header-anchor" href="#select" aria-label="Permalink to “Select”">​</a></h3><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>displayValue</code> trigger slot prop</td><td><code>selectedOption.label</code></td></tr><tr><td><code>data-slot=&quot;trigger-value&quot;</code></td><td>nothing — it marked an invisible element used to measure</td></tr></tbody></table><h3 id="combobox" tabindex="-1">Combobox <a class="header-anchor" href="#combobox" aria-label="Permalink to “Combobox”">​</a></h3><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>slotName</code> on custom options</td><td><code>slot</code>, which dispatches to <code>#item-&lt;slot&gt;</code></td></tr><tr><td><code>searchTerm</code> in the custom-option context</td><td><code>query</code></td></tr><tr><td><code>input</code> emit</td><td><code>@update:query</code></td></tr><tr><td><code>render</code> on options</td><td><code>slots</code></td></tr><tr><td><code>placement</code>, <code>ComboboxPlacement</code></td><td><code>side</code> + <code>align</code></td></tr><tr><td><code>createOption</code></td><td><code>type: &#39;custom&#39;</code> option + <code>condition</code></td></tr><tr><td><code>allowCustomValue</code></td><td><code>type: &#39;custom&#39;</code> option + <code>condition</code></td></tr><tr><td><code>reset()</code> on a template ref</td><td><code>clear()</code></td></tr><tr><td><code>SimpleOption</code>, <code>GroupedOption</code>, <code>SelectableOption</code>, <code>CustomOption</code></td><td>the <code>Combobox</code>-prefixed names</td></tr></tbody></table><h3 id="multiselect" tabindex="-1">MultiSelect <a class="header-anchor" href="#multiselect" aria-label="Permalink to “MultiSelect”">​</a></h3><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>compareFn</code> prop</td><td>nothing — an option is selected when its <code>value</code> is in <code>modelValue</code></td></tr><tr><td><code>displayValue</code> slot prop</td><td><code>summary</code> on <code>#summary</code>, or <code>selectedOptions</code></td></tr><tr><td><code>toggleOpen</code> slot prop</td><td><code>setOpen(boolean)</code></td></tr></tbody></table><h3 id="dropdown-and-contextmenu" tabindex="-1">Dropdown and ContextMenu <a class="header-anchor" href="#dropdown-and-contextmenu" aria-label="Permalink to “Dropdown and ContextMenu”">​</a></h3><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>placement</code> prop, <code>DropdownPlacement</code> type</td><td><code>align</code></td></tr><tr><td><code>{ group, items }</code></td><td><code>{ group, options }</code></td></tr><tr><td><code>component:</code> option rows</td><td><code>slots: { item: fn }</code></td></tr><tr><td><code>DropdownExposed</code> type</td><td>nothing — it described a template ref surface that never existed; use <code>v-model:open</code> or the <code>close</code> slot prop</td></tr></tbody></table><p>All three behavioral removals are silent in plain-JS apps — the old code still runs and renders wrong instead of failing — so check each one. TypeScript callers get errors instead: the removed keys stay in the types as <code>never</code>. A dev-mode console warning also fires when <code>items</code> or <code>component</code> reaches the menu at runtime.</p><p><strong><code>placement</code> is ignored now.</strong> The menu falls back to <code>align=&quot;start&quot;</code>, so a right-aligned menu quietly moves left:</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Dropdown</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">options</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">options</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> placement</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">right</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Dropdown</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">options</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">options</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> placement</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">center</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Dropdown</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">options</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">options</span><span class="s_w1p9wo">&quot;</span><span class="s_suc1p8"> align</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">end</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Dropdown</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">options</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">options</span><span class="s_w1p9wo">&quot;</span><span class="s_suc1p8"> align</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">center</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span></code></pre></div><p><strong>A <code>{ group, items }</code> entry renders an empty menu</strong> — the group resolves to zero options:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">// Before</span></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> actions</span><span class="s_2ekfrt"> =</span><span class="s_13ahmt"> [{</span><span class="s_r4oegk"> group</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">Edit</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_r4oegk"> items</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> [{</span><span class="s_r4oegk"> label</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">Rename</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_r4oegk"> onClick</span><span class="s_1jjt6x">:</span><span class="s_11933w"> rename</span><span class="s_13ahmt"> }]</span><span class="s_13ahmt"> }]</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">// After</span></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> actions</span><span class="s_2ekfrt"> =</span><span class="s_13ahmt"> [{</span><span class="s_r4oegk"> group</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">Edit</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_r4oegk"> options</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> [{</span><span class="s_r4oegk"> label</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">Rename</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_r4oegk"> onClick</span><span class="s_1jjt6x">:</span><span class="s_11933w"> rename</span><span class="s_13ahmt"> }]</span><span class="s_13ahmt"> }]</span></span></code></pre></div><p><strong>A <code>component:</code> row renders as a plain action row</strong> using its <code>label</code>, which for most of these rows is empty:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">// Before</span></span>
<span class="line"><span class="s_13ahmt">{ </span><span class="s_g1fsda">component</span><span class="s_1jjt6x">:</span><span class="s_indoxt"> h</span><span class="s_13ahmt">(</span><span class="s_22m8k2">Button</span><span class="s_1jjt6x">,</span><span class="s_13ahmt"> { </span><span class="s_r4oegk">theme</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">red</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> }</span><span class="s_1jjt6x">,</span><span class="s_13ahmt"> () </span><span class="s_50ecpt">=&gt;</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">Delete</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">) }</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">// After</span></span>
<span class="line"><span class="s_13ahmt">{</span></span>
<span class="line"><span class="s_g1fsda">  label</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">Delete</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_g1fsda">  slots</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_g1fsda">    item</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> () </span><span class="s_50ecpt">=&gt;</span><span class="s_indoxt"> h</span><span class="s_13ahmt">(</span><span class="s_22m8k2">Button</span><span class="s_1jjt6x">,</span><span class="s_13ahmt"> { </span><span class="s_r4oegk">theme</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">red</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> }</span><span class="s_1jjt6x">,</span><span class="s_13ahmt"> () </span><span class="s_50ecpt">=&gt;</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">Delete</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">)</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">  }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">}</span></span></code></pre></div><p>These apply identically to <code>ContextMenu</code>, which shares the option shape (<code>ContextMenuComponentOption</code> is removed with <code>DropdownComponentOption</code>).</p><h3 id="custom-rows" tabindex="-1">Custom rows <a class="header-anchor" href="#custom-rows" aria-label="Permalink to “Custom rows”">​</a></h3><p><code>Select</code> and <code>MultiSelect</code> lost <code>#option</code>, and <code>Combobox</code> lost <code>render</code>. They were the same idea — hand the whole row to the consumer. All three are replaced by region slots on a row the component owns.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before: one slot for the whole label area --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Select</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">chartType</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">options</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">options</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #option=&quot;{ option }&quot;&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;div class=&quot;flex items-center gap-2&quot;&gt;</span></span>
<span class="line"><span class="s_6am9cx">      &lt;component :is=&quot;option.icon&quot; class=&quot;size-4&quot; /&gt;</span></span>
<span class="line"><span class="s_6am9cx">      &lt;span&gt;{{ option.label }}&lt;/span&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;/div&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;/template&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Select</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After: one slot per region --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Select</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">chartType</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">options</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">options</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #item-prefix=&quot;{ item }&quot;&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;component :is=&quot;item.icon&quot; class=&quot;size-4&quot; /&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;/template&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #item-label=&quot;{ item }&quot;&gt;{{ item.label }}&lt;/template&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Select</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p>An icon is rendered from <code>option.icon</code> automatically now, so the common case needs no slot at all — set <code>icon</code> and drop both templates.</p><p><code>Combobox</code>&#39;s <code>render</code> moves the same way: the function form becomes <code>slots.item</code>, and the object form maps to <code>slots</code> key for key. Use these for lists built in JavaScript, where no template is in reach:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> users</span><span class="s_2ekfrt"> =</span><span class="s_22m8k2"> fetchedUsers</span><span class="s_1jjt6x">.</span><span class="s_indoxt">map</span><span class="s_13ahmt">((</span><span class="s_fsg3al">user</span><span class="s_13ahmt">)</span><span class="s_50ecpt"> =&gt;</span><span class="s_13ahmt"> ({</span></span>
<span class="line"><span class="s_r4oegk">  label</span><span class="s_1jjt6x">:</span><span class="s_22m8k2"> user</span><span class="s_1jjt6x">.</span><span class="s_11933w">name</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  value</span><span class="s_1jjt6x">:</span><span class="s_22m8k2"> user</span><span class="s_1jjt6x">.</span><span class="s_11933w">id</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  slots</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_indoxt">    prefix</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> (</span><span class="s_1jjt6x">{</span><span class="s_fsg3al"> item</span><span class="s_1jjt6x"> }</span><span class="s_13ahmt">)</span><span class="s_50ecpt"> =&gt;</span><span class="s_indoxt"> h</span><span class="s_13ahmt">(</span><span class="s_22m8k2">Avatar</span><span class="s_1jjt6x">,</span><span class="s_13ahmt"> {</span><span class="s_12xt1b"> image</span><span class="s_1jjt6x">:</span><span class="s_22m8k2"> item</span><span class="s_1jjt6x">.</span><span class="s_11933w">image</span><span class="s_1jjt6x">,</span><span class="s_12xt1b"> class</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">size-4</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> })</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">  }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">}))</span></span></code></pre></div><p>Full-row takeover is still there — <code>slots.item</code>, or the <code>#item</code> template slot.</p><h3 id="custom-options-on-combobox" tabindex="-1">Custom options on Combobox <a class="header-anchor" href="#custom-options-on-combobox" aria-label="Permalink to “Custom options on Combobox”">​</a></h3><p>Two renames land on the same option object:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">// Before</span></span>
<span class="line"><span class="s_13ahmt">{</span></span>
<span class="line"><span class="s_g1fsda">  type</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">custom</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_g1fsda">  key</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">create-new</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_g1fsda">  slotName</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">create-new</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_g1fsda">  onClick</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> (</span><span class="s_1jjt6x">{</span><span class="s_fsg3al"> searchTerm</span><span class="s_1jjt6x"> }</span><span class="s_13ahmt">) </span><span class="s_50ecpt">=&gt;</span><span class="s_indoxt"> createItem</span><span class="s_13ahmt">(</span><span class="s_22m8k2">searchTerm</span><span class="s_13ahmt">)</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_g1fsda">  condition</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> (</span><span class="s_1jjt6x">{</span><span class="s_fsg3al"> searchTerm</span><span class="s_1jjt6x"> }</span><span class="s_13ahmt">) </span><span class="s_50ecpt">=&gt;</span><span class="s_indoxt"> Boolean</span><span class="s_13ahmt">(</span><span class="s_22m8k2">searchTerm</span><span class="s_13ahmt">)</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">}</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">// After</span></span>
<span class="line"><span class="s_13ahmt">{</span></span>
<span class="line"><span class="s_g1fsda">  type</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">custom</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_g1fsda">  key</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">create-new</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_g1fsda">  slot</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">create-new</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_g1fsda">  onClick</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> (</span><span class="s_1jjt6x">{</span><span class="s_fsg3al"> query</span><span class="s_1jjt6x"> }</span><span class="s_13ahmt">) </span><span class="s_50ecpt">=&gt;</span><span class="s_indoxt"> createItem</span><span class="s_13ahmt">(</span><span class="s_22m8k2">query</span><span class="s_13ahmt">)</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_g1fsda">  condition</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> (</span><span class="s_1jjt6x">{</span><span class="s_fsg3al"> query</span><span class="s_1jjt6x"> }</span><span class="s_13ahmt">) </span><span class="s_50ecpt">=&gt;</span><span class="s_indoxt"> Boolean</span><span class="s_13ahmt">(</span><span class="s_22m8k2">query</span><span class="s_13ahmt">)</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">}</span></span></code></pre></div><p>The slot the row lands in is renamed with it. <code>#create-new</code> becomes <code>#item-create-new</code>, and it receives <code>{ item, query, selected }</code> instead of <code>{ option, searchTerm }</code>. <code>onClick</code> and <code>condition</code> keep their names.</p><h3 id="if-you-used-allowcustomvalue" tabindex="-1">If you used <code>allowCustomValue</code> <a class="header-anchor" href="#if-you-used-allowcustomvalue" aria-label="Permalink to “If you used allowCustomValue”">​</a></h3><p><code>Combobox</code> had a prop that accepted the typed text as the value and drew a built-in <code>Create &quot;…&quot;</code> row. It is gone. It could not do anything a custom row cannot, and it hardcoded the row — no way to change the label, add an icon, or say when it appears.</p><p>Build the row instead. It commits on click and on Enter, because Enter picks the highlighted row:</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> value</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> ref</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;&#39;</span><span class="s_13ahmt">)</span></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> people</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> ref</span><span class="s_13ahmt">([</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">John Doe</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">Jane Doe</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">])</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> options</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> computed</span><span class="s_13ahmt">(()</span><span class="s_50ecpt"> =&gt;</span><span class="s_13ahmt"> [</span></span>
<span class="line"><span class="s_fjrnv8">  ...</span><span class="s_22m8k2">people</span><span class="s_1jjt6x">.</span><span class="s_11933w">value</span><span class="s_1jjt6x">.</span><span class="s_indoxt">map</span><span class="s_13ahmt">((</span><span class="s_fsg3al">p</span><span class="s_13ahmt">)</span><span class="s_50ecpt"> =&gt;</span><span class="s_13ahmt"> ({</span><span class="s_r4oegk"> label</span><span class="s_1jjt6x">:</span><span class="s_11933w"> p</span><span class="s_1jjt6x">,</span><span class="s_r4oegk"> value</span><span class="s_1jjt6x">:</span><span class="s_11933w"> p</span><span class="s_13ahmt"> }))</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">  {</span></span>
<span class="line"><span class="s_r4oegk">    type</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">custom</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">    key</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">create</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">    label</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">Create</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">    slot</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">create</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_indoxt">    condition</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> (</span><span class="s_1jjt6x">{</span><span class="s_fsg3al"> query</span><span class="s_1jjt6x"> }</span><span class="s_13ahmt">)</span><span class="s_50ecpt"> =&gt;</span></span>
<span class="line"><span class="s_indoxt">      Boolean</span><span class="s_13ahmt">(</span><span class="s_22m8k2">query</span><span class="s_1jjt6x">.</span><span class="s_indoxt">trim</span><span class="s_13ahmt">())</span><span class="s_50ecpt"> &amp;&amp;</span><span class="s_50ecpt"> !</span><span class="s_22m8k2">people</span><span class="s_1jjt6x">.</span><span class="s_11933w">value</span><span class="s_1jjt6x">.</span><span class="s_indoxt">includes</span><span class="s_13ahmt">(</span><span class="s_22m8k2">query</span><span class="s_1jjt6x">.</span><span class="s_indoxt">trim</span><span class="s_13ahmt">())</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_indoxt">    onClick</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> (</span><span class="s_1jjt6x">{</span><span class="s_fsg3al"> query</span><span class="s_1jjt6x"> }</span><span class="s_13ahmt">)</span><span class="s_50ecpt"> =&gt;</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_22m8k2">      value</span><span class="s_1jjt6x">.</span><span class="s_11933w">value</span><span class="s_2ekfrt"> =</span><span class="s_22m8k2"> query</span><span class="s_1jjt6x">.</span><span class="s_indoxt">trim</span><span class="s_13ahmt">()</span></span>
<span class="line"><span class="s_13ahmt">    }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">  }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">])</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;</span><span class="s_wac0bt">Combobox</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">value</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> :options</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">options</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">    &lt;</span><span class="s_1uuh8p">template</span><span class="s_1jjt6x"> #</span><span class="s_1i4ay4">item-create</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">{</span><span class="s_22m8k2"> query</span><span class="s_13ahmt"> }</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span><span class="s_6am9cx">Create &quot;{{ query }}&quot;</span><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;/</span><span class="s_wac0bt">Combobox</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p>A <code>modelValue</code> that matches no option is kept regardless — the trigger falls back to the raw string — so nothing else changes.</p><p><code>dialog.prompt</code>&#39;s <code>allowCreate</code> field option is unaffected; it now builds this row internally.</p><h3 id="if-you-filter-on-the-server" tabindex="-1">If you filter on the server <a class="header-anchor" href="#if-you-filter-on-the-server" aria-label="Permalink to “If you filter on the server”">​</a></h3><p><code>Combobox</code> and <code>MultiSelect</code> filter their options in the browser by default. When the options already come back from a search endpoint, that filters them a second time and drops fuzzy, ranked, or id-based matches. Pass <code>:filterable=&quot;false&quot;</code> to turn it off. Apps that forked the component for this reason can move back.</p><p>For the removed <code>Autocomplete</code>, see <a href="#autocomplete-removed">Autocomplete (removed)</a>.</p><h2 id="popover-hovercard-tooltip" tabindex="-1">Popover / HoverCard / Tooltip <a class="header-anchor" href="#popover-hovercard-tooltip" aria-label="Permalink to “Popover / HoverCard / Tooltip”">​</a></h2><p>The v0 <code>Popover</code> API is <strong>removed</strong> in <code>1.0.0</code>. Nothing is aliased and nothing warns — Vue drops an unknown prop or slot without complaining, so a missed call site renders a popover with no trigger, or an empty one. Check every <code>&lt;Popover&gt;</code> in your app.</p><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>#target</code> slot</td><td><code>#trigger</code> — reka wires the click, so drop your own click handler</td></tr><tr><td><code>#body</code> slot</td><td><code>#default</code> + <code>bare</code> prop (renders without the panel shell)</td></tr><tr><td><code>#body-main</code> slot</td><td><code>#default</code></td></tr><tr><td><code>togglePopover</code> / <code>updatePosition</code> slot props</td><td><code>toggle</code> (<code>updatePosition</code> is gone — reka repositions on its own)</td></tr><tr><td><code>placement=&quot;bottom-start&quot;</code></td><td><code>side=&quot;bottom&quot;</code> + <code>align=&quot;start&quot;</code> (a bare side like <code>placement=&quot;bottom&quot;</code> maps to <code>align=&quot;center&quot;</code>)</td></tr><tr><td><code>show</code> / <code>v-model:show</code></td><td><code>open</code> / <code>v-model:open</code></td></tr><tr><td><code>update:show</code> emit</td><td><code>update:open</code></td></tr><tr><td><code>hideOnBlur</code></td><td><code>dismissible</code></td></tr><tr><td><code>matchTargetWidth</code></td><td><code>matchTriggerWidth</code></td></tr><tr><td><code>trigger=&quot;hover&quot;</code> (+ <code>hoverDelay</code> / <code>leaveDelay</code>)</td><td>the <a href="./components/hovercard"><code>HoverCard</code></a> component</td></tr><tr><td><code>popoverClass</code></td><td><code>data-slot</code> CSS hooks</td></tr><tr><td><code>transition=&quot;default&quot;</code></td><td>built-in motion — delete the prop</td></tr><tr><td><code>PopoverPlacement</code> type</td><td><code>PopoverSide</code> + <code>PopoverAlign</code></td></tr><tr><td><code>PopoverLegacySlotProps</code> type</td><td><code>PopoverSlotProps</code></td></tr><tr><td><code>NestedPopover</code></td><td><code>Popover</code> — it never nested, and it was the last <code>@popperjs/core</code> consumer</td></tr></tbody></table><h3 id="trigger-and-content-slots" tabindex="-1">Trigger and content slots <a class="header-anchor" href="#trigger-and-content-slots" aria-label="Permalink to “Trigger and content slots”">​</a></h3><p><code>#target</code> did not wire anything — you called <code>togglePopover</code> yourself. <code>#trigger</code> renders through reka&#39;s <code>PopoverTrigger</code> as-child, which brings the click handler, keyboard support and <code>aria-expanded</code> with it. <strong>Keeping your click handler makes the popover toggle twice and stay shut.</strong></p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Popover</span><span class="s_1i4ay4"> placement</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">bottom-end</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #target=&quot;{ togglePopover }&quot;&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;Button label=&quot;Filter&quot; @click=&quot;togglePopover&quot; /&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;/template&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #body-main=&quot;{ close }&quot;&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;FilterPanel @done=&quot;close&quot; /&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;/template&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Popover</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Popover</span><span class="s_1i4ay4"> side</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">bottom</span><span class="s_w1p9wo">&quot;</span><span class="s_suc1p8"> align</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">end</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #trigger&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;Button label=&quot;Filter&quot; /&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;/template&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #default=&quot;{ close }&quot;&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;FilterPanel @done=&quot;close&quot; /&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;/template&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Popover</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p><code>#body</code> rendered outside the panel shell, so it maps to <code>#default</code> <strong>plus</strong><code>bare</code> — without <code>bare</code> your content ends up inside a second panel.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Popover</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #body&gt;&lt;EmojiPicker /&gt;&lt;/template&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Popover</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Popover</span><span class="s_1i4ay4"> bare</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;EmojiPicker /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Popover</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><h3 id="driving-the-popover-yourself" tabindex="-1">Driving the popover yourself <a class="header-anchor" href="#driving-the-popover-yourself" aria-label="Permalink to “Driving the popover yourself”">​</a></h3><p>If your trigger needs custom timing (a delayed open, a drag that must not open it), bind <code>open</code> and accept only closes, so the trigger&#39;s own toggle cannot open it behind your back:</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Popover</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">open</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">isOpen</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> @</span><span class="s_1i4ay4">update</span><span class="s_1jjt6x">:</span><span class="s_1i4ay4">open</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">(</span><span class="s_fsg3al">value</span><span class="s_13ahmt">)</span><span class="s_50ecpt"> =&gt;</span><span class="s_50ecpt"> !</span><span class="s_22m8k2">value</span><span class="s_50ecpt"> &amp;&amp;</span><span class="s_13ahmt"> (</span><span class="s_22m8k2">isOpen</span><span class="s_2ekfrt"> =</span><span class="s_40mev6"> false</span><span class="s_13ahmt">)</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #trigger&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;div @click=&quot;onClick&quot;&gt;…&lt;/div&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;/template&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Popover</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><h3 id="slot-props" tabindex="-1">Slot props <a class="header-anchor" href="#slot-props" aria-label="Permalink to “Slot props”">​</a></h3><p><code>#trigger</code> and <code>#default</code> receive <code>{ open, close, toggle }</code>.</p><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>isOpen</code></td><td><code>open</code></td></tr><tr><td><code>open</code> (a method to call)</td><td><code>toggle</code>, or nothing — see below</td></tr><tr><td><code>togglePopover</code></td><td><code>toggle</code></td></tr><tr><td><code>updatePosition</code></td><td>gone; reka repositions on its own</td></tr></tbody></table><p><code>open</code> is now the boolean state, which is what it already means on <code>Dropdown</code>, <code>Select</code>, <code>MultiSelect</code>, <code>HoverCard</code> and <code>Sidebar</code>. It used to be a method on <code>Popover</code> alone.</p><p>This one is silent and worth grepping for: a destructured <code>isOpen</code> becomes <code>undefined</code>, so a class bound to it stops applying with no error.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">template</span><span class="s_1jjt6x"> #</span><span class="s_1i4ay4">trigger</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">{</span><span class="s_22m8k2"> isOpen</span><span class="s_13ahmt"> }</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;</span><span class="s_1uuh8p">Button</span><span class="s_1i4ay4"> :class</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">isOpen &amp;&amp; &#39;ring-2&#39;</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> label</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">Filter</span><span class="s_w1p9wo">&quot;</span><span class="s_28rvie"> /</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">template</span><span class="s_1jjt6x"> #</span><span class="s_1i4ay4">trigger</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">{</span><span class="s_22m8k2"> open</span><span class="s_13ahmt"> }</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;</span><span class="s_1uuh8p">Button</span><span class="s_1i4ay4"> :class</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">open &amp;&amp; &#39;ring-2&#39;</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> label</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">Filter</span><span class="s_w1p9wo">&quot;</span><span class="s_28rvie"> /</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p>Most triggers need nothing at all — <code>#trigger</code> wires its own click, so the <code>open()</code> method it used to hand out had no callers. <code>toggle</code> is there for the cases that drive it by hand.</p><h3 id="attributes-are-not-inherited" tabindex="-1">Attributes are not inherited <a class="header-anchor" href="#attributes-are-not-inherited" aria-label="Permalink to “Attributes are not inherited”">​</a></h3><p><code>&lt;Popover class=&quot;…&quot;&gt;</code> and <code>&lt;Popover :style=&quot;…&quot;&gt;</code> used to land on a wrapper the legacy <code>#target</code> rendered. <code>#trigger</code> is as-child and renders no wrapper, so those attributes now go nowhere. Move them onto the element inside <code>#trigger</code>.</p><h3 id="hover-panels" tabindex="-1">Hover panels <a class="header-anchor" href="#hover-panels" aria-label="Permalink to “Hover panels”">​</a></h3><p>Hover-driven panels move to the <a href="./components/hovercard"><code>HoverCard</code></a> component, which keeps <code>hoverDelay</code> / <code>leaveDelay</code> in seconds.</p><h3 id="tooltip" tabindex="-1">Tooltip <a class="header-anchor" href="#tooltip" aria-label="Permalink to “Tooltip”">​</a></h3><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>placement=&quot;right&quot;</code></td><td><code>side=&quot;right&quot;</code></td></tr><tr><td><code>arrowClass</code></td><td><code>[data-slot=&quot;arrow&quot;]</code> CSS, or <code>offset</code> to shift the bubble</td></tr><tr><td><code>#body</code></td><td><code>#content</code> (add <code>bare</code> if the content owns its surface)</td></tr></tbody></table><p>All three are silent — the tooltip keeps working, it just points the wrong way, loses the styling, or comes up empty. <code>arrowClass</code> was documented as the arrow&#39;s fill, but was mostly used to nudge the bubble&#39;s position; <code>offset</code> does that directly.</p><p><code>#default</code> is still the <strong>trigger</strong>. That is deliberate and is not changing.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Tooltip</span><span class="s_1i4ay4"> text</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">Preview</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> placement</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">bottom</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> arrow-class</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">mb-3</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;Button label=&quot;Preview&quot; /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Tooltip</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Tooltip</span><span class="s_1i4ay4"> text</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">Preview</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> side</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">bottom</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">offset</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_40mev6">12</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;Button label=&quot;Preview&quot; /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Tooltip</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p><code>#body</code> replaced the whole bubble, surface included, so call sites hand-copied the bubble&#39;s own classes to get them back. <code>#content</code> renders inside the bubble, so that wrapper goes away:</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Tooltip</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #body&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;div</span></span>
<span class="line"><span class="s_6am9cx">      class=&quot;rounded bg-surface-gray-10 px-2 py-1 text-xs text-ink-base shadow-xl&quot;</span></span>
<span class="line"><span class="s_6am9cx">    &gt;</span></span>
<span class="line"><span class="s_6am9cx">      &lt;span&gt;Hide password&lt;/span&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;/div&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;/template&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;Button icon=&quot;eye&quot; /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Tooltip</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Tooltip</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #content&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;span&gt;Hide password&lt;/span&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;/template&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;Button icon=&quot;eye&quot; /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Tooltip</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p>If the content really does bring its own surface — an image preview, say — keep it and add <code>bare</code>:</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Tooltip</span><span class="s_1i4ay4"> bare</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #content&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;img :src=&quot;url&quot; class=&quot;max-h-40 rounded shadow-xl&quot; /&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;/template&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;span class=&quot;truncate&quot;&gt;{{ filename }}&lt;/span&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Tooltip</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><h2 id="inputs" tabindex="-1">Inputs <a class="header-anchor" href="#inputs" aria-label="Permalink to “Inputs”">​</a></h2><p>Covers <code>TextInput</code>, <code>Textarea</code>, <code>Password</code>, <code>Checkbox</code>, <code>Switch</code>, <code>Rating</code>, <code>Slider</code>. All share the labeling contract (<code>label</code> / <code>description</code> / <code>error</code> / <code>required</code>).</p><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>&lt;Input&gt;</code> (removed)</td><td><code>&lt;TextInput&gt;</code> or <code>FormControl</code></td></tr><tr><td><code>Rating</code> <code>:rating_from</code></td><td><code>:max</code></td></tr><tr><td><code>Rating</code> <code>:readonly</code></td><td><code>:disabled</code></td></tr><tr><td><code>Switch</code> <code>@change</code></td><td><code>@update:modelValue</code></td></tr><tr><td><code>Switch.labelClasses</code></td><td><code>data-*</code> styling hooks</td></tr><tr><td><code>Checkbox.padding</code></td><td><code>padded</code></td></tr><tr><td><code>Password</code> <code>:value</code> prop (removed)</td><td><code>v-model</code></td></tr><tr><td><code>TextInput</code> / <code>Textarea</code> ref <code>.el</code></td><td>ref <code>.inputElement</code></td></tr></tbody></table><p>The first five rows are <strong>removed</strong>, not aliased. The old names are silently ignored: a <code>Rating</code> with <code>:rating_from=&quot;10&quot;</code> renders 5 stars, a <code>:readonly</code> Rating becomes interactive, a <code>Switch</code> <code>@change</code> handler never fires, and <code>labelClasses</code> / <code>Checkbox.padding</code> stop styling anything. Nothing breaks at build time, so grep for these names when upgrading.</p><p><code>Slider</code> no longer hardcodes <code>aria-label=&quot;Volume&quot;</code>. Pass <code>label</code> explicitly so the control is announced correctly.</p><h3 id="password-—-value-prop-removed" tabindex="-1">Password — <code>value</code> prop removed <a class="header-anchor" href="#password-—-value-prop-removed" aria-label="Permalink to “Password — value prop removed”">​</a></h3><p><code>value</code> was a deprecated alternate way to set the password, seeding <code>v-model</code> on mount. It&#39;s gone. <code>:value</code> now falls through as a plain HTML attribute on the native <code>&lt;input&gt;</code> instead of seeding the model — the field still renders, so nothing throws or warns.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Password</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">password</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">value</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">initialValue</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Password</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">password</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_22m8k2">password</span><span class="s_1jjt6x">.</span><span class="s_11933w">value</span><span class="s_2ekfrt"> =</span><span class="s_22m8k2"> initialValue</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><h3 id="textinput-textarea-password-—-ref-surface" tabindex="-1"><code>TextInput</code>, <code>Textarea</code>, <code>Password</code> — ref surface <a class="header-anchor" href="#textinput-textarea-password-—-ref-surface" aria-label="Permalink to “TextInput, Textarea, Password — ref surface”">​</a></h3><p><code>TextInput</code> and <code>Textarea</code> handed back <code>{ el }</code>, a raw ref on the native element. It&#39;s now <code>{ focus, inputElement }</code>: call <code>focus(options?)</code> to move keyboard focus, and read <code>inputElement</code> for the native element itself (a computed, so it can&#39;t be reassigned). <code>Password</code> gains the same pair — it previously exposed nothing.</p><p>This is silent for plain JS: <code>ref.value.el</code> becomes <code>undefined</code> at runtime instead of throwing. A typed ref catches it as a build-time error instead.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">TextInput</span><span class="s_1i4ay4"> ref</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">input</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_50ecpt">function</span><span class="s_indoxt"> focusIt</span><span class="s_13ahmt">()</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_22m8k2">  input</span><span class="s_1jjt6x">.</span><span class="s_11933w">value</span><span class="s_1jjt6x">.</span><span class="s_11933w">el</span><span class="s_1jjt6x">.</span><span class="s_indoxt">focus</span><span class="s_13ahmt">({ </span><span class="s_r4oegk">preventScroll</span><span class="s_1jjt6x">:</span><span class="s_40mev6"> true</span><span class="s_13ahmt"> })</span></span>
<span class="line"><span class="s_13ahmt">}</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">TextInput</span><span class="s_1i4ay4"> ref</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">input</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_50ecpt">function</span><span class="s_indoxt"> focusIt</span><span class="s_13ahmt">()</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_22m8k2">  input</span><span class="s_1jjt6x">.</span><span class="s_11933w">value</span><span class="s_1jjt6x">.</span><span class="s_indoxt">focus</span><span class="s_13ahmt">({ </span><span class="s_r4oegk">preventScroll</span><span class="s_1jjt6x">:</span><span class="s_40mev6"> true</span><span class="s_13ahmt"> })</span></span>
<span class="line"><span class="s_13ahmt">}</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p><code>Duration</code> already exposed <code>focus()</code>; it now takes the same <code>options?</code> parameter as the rest of the family.</p><h2 id="fileuploader" tabindex="-1">FileUploader <a class="header-anchor" href="#fileuploader" aria-label="Permalink to “FileUploader”">​</a></h2><p><code>FileUploader</code> reached structural bar in <code>1.0.0</code>: TypeScript, flat props, and a security fix to the default it shares with <code>useFileUpload</code> / <code>FileUploadHandler</code>.</p><h3 id="uploads-default-to-private" tabindex="-1">Uploads default to private <a class="header-anchor" href="#uploads-default-to-private" aria-label="Permalink to “Uploads default to private”">​</a></h3><p><code>useFileUpload()</code> and <code>FileUploadHandler</code> now resolve an upload with no stated <code>private</code> / <code>is_private</code> to <strong>private</strong>, not public. <code>FileUploader</code> itself is unaffected — it has uploaded private by default since <code>v1.0.0-beta.21</code>; this only changes the two lower-level primitives, called directly.</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">// Same call, before and after — the result changes:</span></span>
<span class="line"><span class="s_29n2kq">await</span><span class="s_indoxt"> useFileUpload</span><span class="s_13ahmt">()</span><span class="s_1jjt6x">.</span><span class="s_indoxt">upload</span><span class="s_13ahmt">(</span><span class="s_22m8k2">file</span><span class="s_1jjt6x">,</span><span class="s_13ahmt"> {})</span></span>
<span class="line"><span class="s_29n2kq">await</span><span class="s_2ekfrt"> new</span><span class="s_indoxt"> FileUploadHandler</span><span class="s_13ahmt">()</span><span class="s_1jjt6x">.</span><span class="s_indoxt">upload</span><span class="s_13ahmt">(</span><span class="s_22m8k2">file</span><span class="s_1jjt6x">,</span><span class="s_13ahmt"> {})</span></span>
<span class="line"><span class="s_1th9sy">// Before: is_private=0 (public).  After: is_private=1 (private).</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">// State the intent explicitly instead of relying on the default:</span></span>
<span class="line"><span class="s_29n2kq">await</span><span class="s_indoxt"> useFileUpload</span><span class="s_13ahmt">()</span><span class="s_1jjt6x">.</span><span class="s_indoxt">upload</span><span class="s_13ahmt">(</span><span class="s_22m8k2">file</span><span class="s_1jjt6x">,</span><span class="s_13ahmt"> {</span><span class="s_r4oegk"> private</span><span class="s_1jjt6x">:</span><span class="s_40mev6"> false</span><span class="s_13ahmt"> })</span><span class="s_1th9sy"> // public</span></span>
<span class="line"><span class="s_29n2kq">await</span><span class="s_indoxt"> useFileUpload</span><span class="s_13ahmt">()</span><span class="s_1jjt6x">.</span><span class="s_indoxt">upload</span><span class="s_13ahmt">(</span><span class="s_22m8k2">file</span><span class="s_1jjt6x">,</span><span class="s_13ahmt"> {</span><span class="s_r4oegk"> private</span><span class="s_1jjt6x">:</span><span class="s_40mev6"> true</span><span class="s_13ahmt"> })</span><span class="s_1th9sy"> // private</span></span></code></pre></div><p>If your app serves an uploaded file with no session — an avatar in an email digest, an image embedded on a public page — audit every call that omits <code>private</code> / <code>is_private</code> before upgrading. A file that flips to private returns <code>403</code> to a session-less request instead of the image.</p><h3 id="uploadargs-→-flat-props" tabindex="-1"><code>uploadArgs</code> → flat props <a class="header-anchor" href="#uploadargs-→-flat-props" aria-label="Permalink to “uploadArgs → flat props”">​</a></h3><p>The single <code>uploadArgs</code> object prop is gone. Its commonly-used fields are now flat props on the component:</p><table tabindex="0"><thead><tr><th>Before (<code>uploadArgs</code>)</th><th>After</th></tr></thead><tbody><tr><td><code>private</code> / <code>is_private</code></td><td><code>private</code></td></tr><tr><td><code>folder</code></td><td><code>folder</code></td></tr><tr><td><code>doctype</code></td><td><code>doctype</code></td></tr><tr><td><code>docname</code></td><td><code>docname</code></td></tr><tr><td><code>fieldname</code></td><td><code>fieldname</code></td></tr><tr><td><code>upload_endpoint</code></td><td><code>uploadEndpoint</code></td></tr><tr><td><code>optimize</code></td><td><code>optimize</code></td></tr></tbody></table><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">FileUploader</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">uploadArgs</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">{</span><span class="s_r4oegk"> private</span><span class="s_1jjt6x">: </span><span class="s_40mev6">false</span><span class="s_1jjt6x">, </span><span class="s_r4oegk">folder</span><span class="s_1jjt6x">: </span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">Attachments</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> }</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">FileUploader</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">private</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_40mev6">false</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> folder</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">Attachments</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span></code></pre></div><p>This is silent: <code>uploadArgs</code> isn&#39;t a recognized prop anymore, so Vue passes it through as an inert HTML attribute on the root element. Nothing throws — the options it carried just stop applying, and (combined with the default flip above) a <code>uploadArgs=&quot;{ private: false }&quot;</code> override that used to make an upload public silently starts uploading private instead. <code>grep</code> every <code>&lt;FileUploader&gt;</code> for <code>uploadArgs=</code> / <code>:upload-args=</code> and move each field to its flat prop.</p><p><code>file_url</code>, <code>method</code>, <code>type</code>, <code>params</code>, <code>max_width</code> / <code>max_height</code>, and upload cancellation (<code>signal</code>) have no flat-prop equivalent — they had no measured use on the component. Use <a href="./other/utilities#usefileupload-fileuploadhandler"><code>useFileUpload()</code></a> directly for those.</p><h3 id="template-ref-—-inputref-removed" tabindex="-1">Template ref — <code>inputRef</code> removed <a class="header-anchor" href="#template-ref-—-inputref-removed" aria-label="Permalink to “Template ref — inputRef removed”">​</a></h3><p><code>FileUploader</code> hands back nothing through a template ref, per <a href="https://github.com/frappe/frappe-ui/blob/main/spec/adr/0012-template-ref-surface.md" target="_blank" rel="noreferrer">ADR-0012</a>. <code>inputRef()</code> (a function, despite the name) is gone with nothing in its place — the <code>openFileSelector</code> slot prop already covers what it opened.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">FileUploader</span><span class="s_1i4ay4"> ref</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">uploader</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_22m8k2">uploader</span><span class="s_1jjt6x">.</span><span class="s_11933w">value</span><span class="s_1jjt6x">.</span><span class="s_indoxt">inputRef</span><span class="s_13ahmt">()</span><span class="s_1jjt6x">.</span><span class="s_indoxt">click</span><span class="s_13ahmt">()</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">FileUploader</span><span class="s_1i4ay4"> v-slot</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">{</span><span class="s_22m8k2"> openFileSelector</span><span class="s_13ahmt"> }</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;Button @click=&quot;openFileSelector&quot;&gt;Upload&lt;/Button&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">FileUploader</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><h3 id="default-slot-s-error-prop-—-always-a-string" tabindex="-1">Default slot&#39;s <code>error</code> prop — always a string <a class="header-anchor" href="#default-slot-s-error-prop-—-always-a-string" aria-label="Permalink to “Default slot&#39;s error prop — always a string”">​</a></h3><p>The default slot&#39;s <code>error</code> prop is <code>string | null</code>, no longer <code>unknown</code>. Upload failures were always normalized to a message string; validation failures (a <code>validateFile</code> prop returning an <code>Error</code>) were not, so <code>error</code> could previously be an <code>Error</code> object too. Both paths normalize to a message string now.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before: had to guard against error being a string or an Error --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">template</span><span class="s_1jjt6x"> #</span><span class="s_1i4ay4">default</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">{</span><span class="s_22m8k2"> error</span><span class="s_13ahmt"> }</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  {{ typeof error === &#39;string&#39; ? error : error?.message }}</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After: error is always a string --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">template</span><span class="s_1jjt6x"> #</span><span class="s_1i4ay4">default</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">{</span><span class="s_22m8k2"> error</span><span class="s_13ahmt"> }</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  {{ error }}</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p>This is silent: a slot that only ever did <code>error.message</code> (assuming the <code>Error</code> shape) now renders <code>undefined</code> instead of the validation message.</p><h3 id="filetobase64-and-the-size-limit-helpers-—-no-longer-exported" tabindex="-1"><code>fileToBase64</code> and the size-limit helpers — no longer exported <a class="header-anchor" href="#filetobase64-and-the-size-limit-helpers-—-no-longer-exported" aria-label="Permalink to “fileToBase64 and the size-limit helpers — no longer exported”">​</a></h3><p><code>fileToBase64</code>, <code>formatBytes</code>, <code>getMaxFileSize</code>, and <code>fileSizeLimitMessage</code> are no longer exported from <code>frappe-ui</code>; the import fails at build time. There were no external call sites at the v1 sweep. Computing a file&#39;s base64 representation yourself is a few lines of <code>FileReader.readAsDataURL</code>.</p><h2 id="divider" tabindex="-1">Divider <a class="header-anchor" href="#divider" aria-label="Permalink to “Divider”">​</a></h2><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>action.handler</code></td><td><code>action.onClick</code></td></tr></tbody></table><h2 id="sidebar" tabindex="-1">Sidebar <a class="header-anchor" href="#sidebar" aria-label="Permalink to “Sidebar”">​</a></h2><p><code>Sidebar</code> is a bare frame — compose <code>SidebarHeader</code> / <code>SidebarSection</code> / <code>SidebarLabel</code> / <code>SidebarItem</code> in its default slot instead of passing config-object props. See the <a href="./components/sidebar">Sidebar</a> component page for the full API.</p><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>:header=&quot;{ title, subtitle, menuItems }&quot;</code></td><td><code>&lt;SidebarHeader :title :subtitle :menu-items /&gt;</code> as a child</td></tr><tr><td><code>:sections=&quot;[{ label, items }]&quot;</code></td><td><code>&lt;SidebarLabel&gt;</code> + <code>&lt;SidebarItem&gt;</code> (or <code>&lt;SidebarSection&gt;</code>) as children</td></tr><tr><td><code>&lt;template #header-logo&gt;</code></td><td><code>&lt;SidebarHeader&gt;</code>&#39;s <code>#prefix</code> slot</td></tr><tr><td><code>&lt;template #footer-items&gt;</code></td><td>plain markup in the default slot</td></tr><tr><td><code>&lt;SidebarSection :items=&quot;rows&quot;&gt;</code></td><td><code>&lt;SidebarSection&gt;</code> with <code>&lt;SidebarItem&gt;</code> children</td></tr><tr><td><code>&lt;template #sidebar-item=&quot;{ item }&quot;&gt;</code></td><td>write the <code>&lt;SidebarItem&gt;</code> directly, no slot needed</td></tr><tr><td><code>item.condition</code></td><td><code>v-if</code> on the composed <code>&lt;SidebarItem&gt;</code></td></tr><tr><td><code>SidebarItem.isActive</code></td><td><code>SidebarItem.active</code></td></tr><tr><td><code>SidebarHeader</code>&#39;s <code>#logo</code> slot</td><td><code>#prefix</code> slot</td></tr></tbody></table><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Sidebar</span></span>
<span class="line"><span class="s_1jjt6x">  :</span><span class="s_1i4ay4">header</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">{</span><span class="s_r4oegk"> title</span><span class="s_1jjt6x">: </span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">Frappe CRM</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">, </span><span class="s_r4oegk">subtitle</span><span class="s_1jjt6x">: </span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">crm.frappe.io</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">, </span><span class="s_22m8k2">menuItems</span><span class="s_13ahmt"> }</span><span class="s_w1p9wo">&quot;</span></span>
<span class="line"><span class="s_1jjt6x">  :</span><span class="s_1i4ay4">sections</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">[</span></span>
<span class="line"><span class="s_13ahmt">    {</span><span class="s_r4oegk"> label</span><span class="s_1jjt6x">: </span><span class="s_w1p9wo">&#39;&#39;</span><span class="s_1jjt6x">, </span><span class="s_r4oegk">items</span><span class="s_1jjt6x">: </span><span class="s_13ahmt">[{</span><span class="s_r4oegk"> label</span><span class="s_1jjt6x">: </span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">Leads</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">, </span><span class="s_r4oegk">to</span><span class="s_1jjt6x">: </span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">/leads</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">, </span><span class="s_r4oegk">icon</span><span class="s_1jjt6x">: </span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">lucide-user-plus</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> }]</span><span class="s_13ahmt"> }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">    {</span><span class="s_r4oegk"> label</span><span class="s_1jjt6x">: </span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">Views</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">, </span><span class="s_r4oegk">collapsible</span><span class="s_1jjt6x">: </span><span class="s_40mev6">true</span><span class="s_1jjt6x">, </span><span class="s_r4oegk">items</span><span class="s_1jjt6x">: </span><span class="s_11933w">viewItems</span><span class="s_13ahmt"> }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">  ]</span><span class="s_w1p9wo">&quot;</span></span>
<span class="line"><span class="s_6am9cx">/&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_6am9cx">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_6am9cx">&lt;Sidebar&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;SidebarHeader title=&quot;Frappe CRM&quot; subtitle=&quot;crm.frappe.io&quot; :menu-items=&quot;menuItems&quot; /&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;div class=&quot;flex-1 overflow-y-auto px-2&quot;&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;SidebarItem label=&quot;Leads&quot; to=&quot;/leads&quot; icon=&quot;lucide-user-plus&quot; /&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;SidebarSection label=&quot;Views&quot; collapsible&gt;</span></span>
<span class="line"><span class="s_6am9cx">      &lt;SidebarItem v-for=&quot;item in viewItems&quot; :key=&quot;item.label&quot; v-bind=&quot;item&quot; /&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;/SidebarSection&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;/div&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Sidebar</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p><code>Sidebar</code> no longer wraps the middle list in a scroll container or applies any padding — that&#39;s app-owned now (see the component page&#39;s Collapse section for the full composition contract).</p><h2 id="data-fetching-usedoctype-uselist" tabindex="-1">Data fetching (useDoctype / useList) <a class="header-anchor" href="#data-fetching-usedoctype-uselist" aria-label="Permalink to “Data fetching (useDoctype / useList)”">​</a></h2><p>The write methods on <code>useDoctype</code> (<code>insert</code>, <code>delete</code>, <code>setValue</code>, <code>runDocMethod</code>, <code>runMethod</code>) and on <code>useList</code> (<code>insert</code>, <code>setValue</code>, <code>delete</code>) used to share one request between all their submits. Each one now sends its own request, so the shared-request members are gone.</p><p>Nothing fails to build, so grep for these by hand. The app keeps rendering and then throws the first time the removed member is read — usually the first time someone deletes a row.</p><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>delete.loading &amp;&amp; delete.params.name === row.name</code></td><td><code>delete.isLoading(row.name)</code></td></tr><tr><td><code>setValue.params.name</code></td><td><code>setValue.isLoading(name)</code></td></tr><tr><td><code>delete.execute()</code> / <code>.fetch()</code> / <code>.reload()</code></td><td><code>delete.submit({ name })</code></td></tr><tr><td><code>insert.reset()</code> / <code>.abort()</code></td><td>removed, no replacement</td></tr><tr><td><code>runMethod.isFetching</code> / <code>.isFinished</code></td><td><code>runMethod.loading</code></td></tr><tr><td><code>setValue.promise</code></td><td><code>await setValue.submit(...)</code></td></tr><tr><td><code>delete.url</code></td><td>removed, no replacement</td></tr></tbody></table><p>All eight now have the same five members: <code>submit()</code>, <code>data</code>, <code>error</code>, <code>loading</code> and <code>isLoading()</code>.</p><p><code>isLoading()</code> takes whatever identifies one submit:</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_22m8k2">todos</span><span class="s_1jjt6x">.</span><span class="s_11933w">delete</span><span class="s_1jjt6x">.</span><span class="s_indoxt">isLoading</span><span class="s_13ahmt">(</span><span class="s_22m8k2">row</span><span class="s_1jjt6x">.</span><span class="s_11933w">name</span><span class="s_13ahmt">)</span></span>
<span class="line"><span class="s_22m8k2">todos</span><span class="s_1jjt6x">.</span><span class="s_11933w">setValue</span><span class="s_1jjt6x">.</span><span class="s_indoxt">isLoading</span><span class="s_13ahmt">(</span><span class="s_22m8k2">row</span><span class="s_1jjt6x">.</span><span class="s_11933w">name</span><span class="s_13ahmt">)</span></span>
<span class="line"><span class="s_22m8k2">todos</span><span class="s_1jjt6x">.</span><span class="s_11933w">runDocMethod</span><span class="s_1jjt6x">.</span><span class="s_indoxt">isLoading</span><span class="s_13ahmt">(</span><span class="s_22m8k2">row</span><span class="s_1jjt6x">.</span><span class="s_11933w">name</span><span class="s_1jjt6x">,</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">archive</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">)</span></span>
<span class="line"><span class="s_22m8k2">todos</span><span class="s_1jjt6x">.</span><span class="s_11933w">runMethod</span><span class="s_1jjt6x">.</span><span class="s_indoxt">isLoading</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">sync_all</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">)</span></span>
<span class="line"><span class="s_22m8k2">todos</span><span class="s_1jjt6x">.</span><span class="s_11933w">insert</span><span class="s_1jjt6x">.</span><span class="s_indoxt">isLoading</span><span class="s_13ahmt">()</span><span class="s_1th9sy"> // no argument: a new row has no name yet</span></span></code></pre></div><p><code>insert.isLoading()</code> gives the same answer as <code>insert.loading</code>. It is there so every write method reads the same way.</p><p>More changes you will not see at build time:</p><ul><li><p><code>submit()</code> now resolves with its own response. Code that fired two submits and read the result of the first was receiving the second one&#39;s data, or <code>null</code>. If you queued submits to work around that, you can drop the queue.</p></li><li><p><code>data</code> and <code>error</code> belong to the submit that started last, not the one that answered last. A slow submit that comes back after a newer one writes nothing and clears nothing. It still answers its own caller with its own outcome — resolving with its response, or rejecting with its error.</p></li><li><p><strong><code>data</code> is no longer reset to <code>null</code> when a submit fails.</strong> It used to be, because the shared request cleared it on any not-ok response. It now keeps the last successful response.</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_29n2kq">await</span><span class="s_22m8k2"> todos</span><span class="s_1jjt6x">.</span><span class="s_11933w">setValue</span><span class="s_1jjt6x">.</span><span class="s_indoxt">submit</span><span class="s_13ahmt">({</span><span class="s_r4oegk"> name</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">TODO-1</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_r4oegk"> status</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">Done</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> })</span></span>
<span class="line"><span class="s_29n2kq">await</span><span class="s_22m8k2"> todos</span><span class="s_1jjt6x">.</span><span class="s_11933w">setValue</span><span class="s_1jjt6x">.</span><span class="s_indoxt">submit</span><span class="s_13ahmt">({</span><span class="s_r4oegk"> name</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">TODO-2</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_r4oegk"> status</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">Done</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> })</span><span class="s_1th9sy"> // fails</span></span>
<span class="line"></span>
<span class="line"><span class="s_22m8k2">todos</span><span class="s_1jjt6x">.</span><span class="s_22m8k2">setValue</span><span class="s_1jjt6x">.</span><span class="s_11933w">data</span><span class="s_1th9sy"> // still the TODO-1 response</span></span>
<span class="line"><span class="s_22m8k2">todos</span><span class="s_1jjt6x">.</span><span class="s_22m8k2">setValue</span><span class="s_1jjt6x">.</span><span class="s_11933w">error</span><span class="s_1th9sy"> // the failure</span></span></code></pre></div><p>Test <code>error</code>, not <code>data</code>, to tell a failed submit from a successful one. <code>if (!todos.setValue.data)</code> used to mean &quot;the last save failed&quot; and no longer does.</p></li><li><p><code>error</code> is no longer cleared when a submit starts. It used to be, which erased the error of a sibling submit still in flight. It now stands until the newest submit settles. To blank an error banner while a retry runs, hide it on <code>loading</code> yourself.</p></li><li><p><strong><code>submit()</code> rejects on any failure.</strong> It resolves with the response, or rejects with the error. A failed <code>validate</code> already rejected; a failed request used to resolve with <code>null</code>. Both reject now.</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">// Before</span></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> doc</span><span class="s_2ekfrt"> =</span><span class="s_29n2kq"> await</span><span class="s_22m8k2"> todos</span><span class="s_1jjt6x">.</span><span class="s_11933w">insert</span><span class="s_1jjt6x">.</span><span class="s_indoxt">submit</span><span class="s_13ahmt">({</span><span class="s_r4oegk"> title</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">Buy milk</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> })</span></span>
<span class="line"><span class="s_50ecpt">if</span><span class="s_13ahmt"> (</span><span class="s_50ecpt">!</span><span class="s_22m8k2">doc</span><span class="s_13ahmt">)</span><span class="s_29n2kq"> return</span><span class="s_indoxt"> showError</span><span class="s_13ahmt">(</span><span class="s_22m8k2">todos</span><span class="s_1jjt6x">.</span><span class="s_22m8k2">insert</span><span class="s_1jjt6x">.</span><span class="s_11933w">error</span><span class="s_13ahmt">)</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">// After</span></span>
<span class="line"><span class="s_50ecpt">try</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_252irl">  const</span><span class="s_295sjd"> doc</span><span class="s_2ekfrt"> =</span><span class="s_29n2kq"> await</span><span class="s_22m8k2"> todos</span><span class="s_1jjt6x">.</span><span class="s_11933w">insert</span><span class="s_1jjt6x">.</span><span class="s_indoxt">submit</span><span class="s_13ahmt">({ </span><span class="s_r4oegk">title</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">Buy milk</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> })</span></span>
<span class="line"><span class="s_13ahmt">}</span><span class="s_50ecpt"> catch</span><span class="s_13ahmt"> (</span><span class="s_22m8k2">e</span><span class="s_13ahmt">)</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_indoxt">  showError</span><span class="s_13ahmt">(</span><span class="s_22m8k2">e</span><span class="s_13ahmt">)</span></span>
<span class="line"><span class="s_13ahmt">}</span></span></code></pre></div><p><code>null</code> no longer means &quot;it failed&quot;. A server that answers with <code>null</code> resolves with <code>null</code>, like any other response. Every <code>if (!result)</code> check after a <code>submit()</code> has to become a <code>try</code> / <code>catch</code> or a <code>.catch()</code>, and an unawaited <code>submit()</code> now needs a <code>.catch()</code> or it becomes an unhandled rejection.</p></li><li><p><code>useList</code>&#39;s <code>insert</code> and <code>delete</code> now send to the <code>baseUrl</code> you passed to <code>useList</code>. They used to ignore it and hit the current origin. <code>setValue</code> already honoured it, so all three write methods now agree. <code>useDoctype</code> was never affected.</p></li></ul><h2 id="data-fetching-exports" tabindex="-1">Data fetching (exports) <a class="header-anchor" href="#data-fetching-exports" aria-label="Permalink to “Data fetching (exports)”">​</a></h2><p><code>useFrappeFetch</code> is no longer exported. It is the raw <code>createFetch</code> instance <code>useCall</code>, <code>useDoc</code> and <code>useList</code> are built on: it sets the Frappe headers and parses the response, and leaves the URL, the params and the caching to you. Pick the composable that matches what you are fetching.</p><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>useFrappeFetch(&#39;/api/v2/method/…&#39;)</code></td><td><code>useCall({ url })</code></td></tr><tr><td><code>useFrappeFetch(&#39;/api/v2/document/…&#39;)</code></td><td><code>useDoc({ doctype, name })</code></td></tr><tr><td><code>useFrappeFetch(&#39;/api/v2/document/…?…&#39;)</code></td><td><code>useList({ doctype, … })</code></td></tr></tbody></table><p>This is a build failure at the import, so nothing changes silently.</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">// Before</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">useFrappeFetch</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_252irl">const</span><span class="s_1jjt6x"> {</span><span class="s_295sjd"> data</span><span class="s_1jjt6x"> }</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> useFrappeFetch</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">/api/v2/method/ping</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">)</span><span class="s_1jjt6x">.</span><span class="s_indoxt">get</span><span class="s_13ahmt">()</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">// After</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">useCall</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> ping</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> useCall</span><span class="s_13ahmt">({</span><span class="s_r4oegk"> url</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">/api/v2/method/ping</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> })</span></span></code></pre></div><p><code>FrappeResponseError</code> is exported now. A Frappe error response raises it — it lands on <code>.error</code>, and the write methods above reject with it. The class was never exported, so you could not tell it apart from a network or parse failure. Narrow it with <code>instanceof</code> and you get <code>title</code>, <code>type</code>, <code>indicator</code> and <code>exception</code>:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">FrappeResponseError</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_50ecpt">try</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_29n2kq">  await</span><span class="s_22m8k2"> todos</span><span class="s_1jjt6x">.</span><span class="s_11933w">insert</span><span class="s_1jjt6x">.</span><span class="s_indoxt">submit</span><span class="s_13ahmt">({ </span><span class="s_r4oegk">title</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">Buy milk</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> })</span></span>
<span class="line"><span class="s_13ahmt">}</span><span class="s_50ecpt"> catch</span><span class="s_13ahmt"> (</span><span class="s_22m8k2">e</span><span class="s_13ahmt">)</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_50ecpt">  if</span><span class="s_13ahmt"> (</span><span class="s_22m8k2">e</span><span class="s_2ekfrt"> instanceof</span><span class="s_euu481"> FrappeResponseError</span><span class="s_13ahmt">) {</span></span>
<span class="line"><span class="s_indoxt">    showError</span><span class="s_13ahmt">(</span><span class="s_22m8k2">e</span><span class="s_1jjt6x">.</span><span class="s_11933w">title</span><span class="s_1jjt6x">,</span><span class="s_22m8k2"> e</span><span class="s_1jjt6x">.</span><span class="s_11933w">type</span><span class="s_13ahmt">)</span></span>
<span class="line"><span class="s_13ahmt">  } </span><span class="s_50ecpt">else</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_50ecpt">    throw</span><span class="s_22m8k2"> e</span></span>
<span class="line"><span class="s_13ahmt">  }</span></span>
<span class="line"><span class="s_13ahmt">}</span></span></code></pre></div><h2 id="tree" tabindex="-1">Tree <a class="header-anchor" href="#tree" aria-label="Permalink to “Tree”">​</a></h2><p>The Tree was rebuilt from a single recursive <code>node</code> renderer into a stateful forest. It takes a <code>nodes</code> array and scopes its per-row slots as <code>#item-*</code>. Each node still owns its expansion via an <code>expanded</code> field, now defaulting to open — set <code>expanded: false</code> to collapse one (v0 used <code>defaultCollapsed</code>). The <code>options</code> blob is gone — sizing moves to CSS variables. Keyboard navigation, <code>role=&quot;tree&quot;</code> ARIA, and opt-in drag-and-drop are new.</p><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>:node=&quot;root&quot;</code> (single root object)</td><td><code>:nodes=&quot;[root]&quot;</code> (array of roots)</td></tr><tr><td><code>node.collapsed</code> / internal collapse</td><td><code>node.expanded</code> (inverted, on each node)</td></tr><tr><td><code>:options=&quot;{ rowHeight, indentWidth }&quot;</code></td><td><code>--tree-row-height</code> / <code>--tree-indent</code> CSS vars</td></tr><tr><td><code>:options=&quot;{ showIndentationGuides }&quot;</code></td><td><code>guides=&quot;connectors&quot; | &quot;lines&quot; | &quot;none&quot;</code></td></tr><tr><td><code>:options=&quot;{ defaultCollapsed: true }&quot;</code></td><td><code>expanded: false</code> per node, or <code>v-model:expanded</code> to toggle all</td></tr><tr><td><code>#node=&quot;{ node, isCollapsed, toggleCollapsed }&quot;</code></td><td><code>#item=&quot;{ node, expanded, toggle, … }&quot;</code></td></tr><tr><td><code>#label</code></td><td><code>#item-label</code></td></tr><tr><td><code>#icon</code></td><td>built-in chevron; override via <code>#item</code></td></tr></tbody></table><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Tree</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">node</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">root</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> node-key</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">name</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">options</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">{</span><span class="s_r4oegk"> defaultCollapsed</span><span class="s_1jjt6x">: </span><span class="s_40mev6">false</span><span class="s_13ahmt"> }</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #label=&quot;{ node }&quot;&gt;{{ node.title }}&lt;/template&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Tree</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Tree</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">nodes</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">[</span><span class="s_11933w">root</span><span class="s_13ahmt">]</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> node-key</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">name</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #item-label=&quot;{ node }&quot;&gt;{{ node.title }}&lt;/template&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Tree</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p><code>v-model:expanded</code> is a boolean expand/collapse-all switch (bind it to a button), not a per-node value.</p><p>Drag-and-drop is opt-in: set <code>draggable</code>, gate drops with <code>:move=&quot;({ node, target, position }) =&gt; …&quot;</code>, and persist from <code>@drag-end=&quot;(info) =&gt; …&quot;</code> — <code>info</code> is <code>{ node, from, to, position, oldIndex, newIndex }</code>, or <code>null</code> when the drag is cancelled.</p><h2 id="icons" tabindex="-1">Icons <a class="header-anchor" href="#icons" aria-label="Permalink to “Icons”">​</a></h2><p>The single recommended way to pass an icon anywhere in the library is a <code>lucide-*</code> string (rendered via the Tailwind mask plugin) or a <code>Component</code> escape hatch (P11). <code>FeatherIcon</code> is removed per ADR-0008 — it shipped <code>@deprecated</code> in code, so nothing marked deprecated ships in <code>1.0.0</code>.</p><p><strong>Breaking, loud:</strong> <code>import { FeatherIcon } from &#39;frappe-ui&#39;</code> and <code>&lt;FeatherIcon&gt;</code> fail at the import. Replace a direct usage with the <code>lucide-*</code> class form:</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">FeatherIcon</span><span class="s_1i4ay4"> name</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">plus</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> class</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">size-4</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">span</span><span class="s_1i4ay4"> class</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">lucide-plus size-4</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> aria-hidden</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">true</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span></code></pre></div><p>Feather and lucide share most icon names, so <code>&lt;FeatherIcon name=&quot;x&quot;&gt;</code> → <code>&lt;span class=&quot;lucide-x&quot;&gt;</code> is usually a direct rename — check each name individually against <a href="https://lucide.dev/icons" target="_blank" rel="noreferrer">lucide.dev</a> since a few differ or were renamed.</p><p><strong>Breaking, silent:</strong> every icon-name prop across the library (<code>Button.icon</code> / <code>iconLeft</code> / <code>iconRight</code>, <code>Dialog.icon</code>, <code>Dropdown</code>/<code>ContextMenu</code> item <code>icon</code>, <code>TabButtons</code> options <code>icon</code> / <code>iconLeft</code> / <code>iconRight</code>, the <code>Icon</code> component&#39;s <code>name</code> prop) used to render a bare feather-style name (e.g. <code>&quot;edit&quot;</code>, <code>&quot;chevron-down&quot;</code>) via <code>FeatherIcon</code>. That fallback is gone: an unrecognized string now renders nothing. No build or type error — the icon silently disappears. A dev-mode console warning names the component, the prop, and the offending value once per (component, prop). Prefix the name with <code>lucide-</code>:</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Button</span><span class="s_1i4ay4"> icon</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">plus</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Button</span><span class="s_1i4ay4"> icon</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">lucide-plus</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span></code></pre></div><p>Same for icon-name strings in <code>Dropdown</code> options:</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">// Before</span></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> options</span><span class="s_2ekfrt"> =</span><span class="s_13ahmt"> [{</span><span class="s_r4oegk"> label</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">Edit</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_r4oegk"> icon</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">edit</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> }]</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">// After</span></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> options</span><span class="s_2ekfrt"> =</span><span class="s_13ahmt"> [{</span><span class="s_r4oegk"> label</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">Edit</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_r4oegk"> icon</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">lucide-pen</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> }]</span></span></code></pre></div><h2 id="card-listitem-standalone-toast-removed" tabindex="-1">Card, ListItem, standalone <code>&lt;Toast&gt;</code> (removed) <a class="header-anchor" href="#card-listitem-standalone-toast-removed" aria-label="Permalink to “Card, ListItem, standalone &lt;Toast&gt; (removed)”">​</a></h2><p>Three unmaintained wrappers are gone in v1, per ADR-0008 — each shipped <code>@deprecated</code> in code and had zero call sites left across our census of downstream apps.</p><p><strong><code>Card</code></strong> wrapped a title/subtitle/actions layout with a manual loading state. There&#39;s no drop-in replacement; rebuild the layout with plain markup, using <a href="./components/loadingtext"><code>LoadingText</code></a> or <a href="./components/skeleton"><code>Skeleton</code></a> for the loading state:</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Card</span><span class="s_1i4ay4"> title</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">Title</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> subtitle</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">Subtitle</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">loading</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">loading</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #actions&gt;&lt;Button label=&quot;Edit&quot; /&gt;&lt;/template&gt;</span></span>
<span class="line"><span class="s_6am9cx">  Content</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Card</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">div</span><span class="s_1i4ay4"> class</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">flex flex-col rounded-lg border px-6 py-5</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;div class=&quot;flex items-baseline justify-between&quot;&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;h2 class=&quot;text-lg font-semibold&quot;&gt;Title&lt;/h2&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;Button label=&quot;Edit&quot; /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;/</span><span class="s_1uuh8p">div</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;</span><span class="s_1uuh8p">p</span><span class="s_1i4ay4"> class</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">mt-1.5 text-ink-gray-6</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span><span class="s_6am9cx">Subtitle</span><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">p</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;</span><span class="s_1uuh8p">LoadingText</span><span class="s_50ecpt"> v-if</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">loading</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> class</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">mt-4</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;</span><span class="s_1uuh8p">div</span><span class="s_50ecpt"> v-else</span><span class="s_1i4ay4"> class</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">mt-4</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span><span class="s_6am9cx">Content</span><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">div</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_6am9cx">/</span><span class="s_1uuh8p">div</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p><strong><code>ListItem</code></strong> rendered a title/subtitle/actions row. Same story — no drop-in replacement, rebuild with plain markup:</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">ListItem</span><span class="s_1i4ay4"> title</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">Title</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> subtitle</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">Subtitle</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #actions&gt;&lt;Button label=&quot;Edit&quot; /&gt;&lt;/template&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">ListItem</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">div</span><span class="s_1i4ay4"> class</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">flex items-center justify-between py-3</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;div&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;h3 class=&quot;font-medium&quot;&gt;Title&lt;/h3&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;p class=&quot;text-ink-gray-6&quot;&gt;Subtitle&lt;/p&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;/</span><span class="s_1uuh8p">div</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;</span><span class="s_1uuh8p">Button</span><span class="s_1i4ay4"> label</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">Edit</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_6am9cx">/</span><span class="s_1uuh8p">div</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p><strong>Standalone <code>&lt;Toast&gt;</code></strong> — <code>import { Toast } from &#39;frappe-ui&#39;</code> and <code>&lt;Toast&gt;</code> fail at the import. This only removes the raw <code>ToastRoot</code>-based component; the imperative API is unaffected and is what you almost certainly want:</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Toast</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">:</span><span class="s_1i4ay4">open</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">open</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> message</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">Saved</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> type</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">success</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">toast</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_22m8k2">toast</span><span class="s_1jjt6x">.</span><span class="s_indoxt">success</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">Saved</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">)</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p><code>&lt;ToastProvider&gt;</code> (mount once near your app root) and <code>toast.success()</code> / <code>toast.error()</code> / <code>toast.info()</code> / plain <code>toast()</code> are unchanged.</p><h2 id="tokens" tabindex="-1">Tokens <a class="header-anchor" href="#tokens" aria-label="Permalink to “Tokens”">​</a></h2><p>Run the v2 token codemod from the app you are migrating:</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_euu481">npx</span><span class="s_2d41qv"> --package</span><span class="s_2575z4"> frappe-ui@beta</span><span class="s_2575z4"> tokens-v2</span><span class="s_2d41qv"> --dry-run</span><span class="s_2575z4"> .</span></span></code></pre></div><p>Review the output, then run it without <code>--dry-run</code>:</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_euu481">npx</span><span class="s_2d41qv"> --package</span><span class="s_2575z4"> frappe-ui@beta</span><span class="s_2575z4"> tokens-v2</span><span class="s_2575z4"> .</span></span></code></pre></div><p>The codemod renames espresso color tokens like <code>bg-surface-white</code> to <code>bg-surface-base</code> and merges static text size + weight class pairs, for example <code>text-base font-medium</code> to <code>text-base-medium</code>. Run it once per codebase; the token migration is not idempotent because some v2 names overlap with v0 names.</p><p>After upgrading to <code>frappe-ui@1.0.0-beta.11</code>, run the codemod again. Apps that already ran it will only get the typography correction (<code>text-lg</code> → <code>text-md</code>, <code>text-xl</code> → <code>text-lg</code>, ...). Apps that still have pre-v2 color tokens can pass <code>--force</code>, but review the output carefully because color tokens may double-shift.</p><h3 id="unused-tokens-and-utilities-removed" tabindex="-1">Unused tokens and utilities removed <a class="header-anchor" href="#unused-tokens-and-utilities-removed" aria-label="Permalink to “Unused tokens and utilities removed”">​</a></h3><p>A pre-<code>1.0.0</code> audit (#940) removed the token names below — all had zero call sites across frappe-ui and every consumer app. Each is a <strong>silent</strong> break: the class or <code>--*</code> variable just stops applying, with no build or type error.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_wvjl67">text-tiny</span></span>
<span class="line"><span class="s_wvjl67">text-13xl / text-14xl / text-15xl / text-16xl (and their -medium/-semibold/-bold/-black variants)</span></span>
<span class="line"><span class="s_wvjl67">shadow-status</span></span>
<span class="line"><span class="s_wvjl67">--elevation-status</span></span>
<span class="line"><span class="s_wvjl67">surface-alert-button-default / -info / -success / -warning / -error</span></span>
<span class="line"><span class="s_wvjl67">ink-alert-button-default / -info / -success / -warning / -error</span></span>
<span class="line"><span class="s_wvjl67">surface-alpha-gray-2-overlay</span></span></code></pre></div><p>If your build used any of these, replace them with the nearest step on the regular scale — e.g. <code>text-16xl</code> → <code>text-12xl</code>, <code>shadow-status</code> → <code>shadow-sm</code>, <code>surface-alert-button-error</code> → <code>surface-red-2</code> (or whichever <code>variant</code>+<code>theme</code> pairing the design calls for).</p><h2 id="editor" tabindex="-1">Editor <a class="header-anchor" href="#editor" aria-label="Permalink to “Editor”">​</a></h2><p>The v0 monolith <code>&lt;TextEditor&gt;</code> (imported from <code>frappe-ui</code>) is replaced by the <code>frappe-ui/editor</code> family: a headless <code>&lt;Editor&gt;</code> you compose with <strong>kits</strong> (bundled, configurable extension sets) and <strong>building-block</strong> menus. Everything moves to the <code>frappe-ui/editor</code> subpath; <code>TextEditor</code> and its siblings (<code>TextEditorBubbleMenu</code>, <code>TextEditorFixedMenu</code>, <code>TextEditorFloatingMenu</code>, <code>TextEditorContent</code>, <code>createEditorButton</code>) are removed from top-level <code>frappe-ui</code> in <code>1.0.0</code> — nothing editor-related is exported from root. See the <a href="./molecules/editor">Editor</a> page for the full API and recipes.</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">// Before</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">TextEditor</span><span class="s_1jjt6x">,</span><span class="s_4q1z3w"> TextEditorFixedMenu</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_1th9sy">// After</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_4q1z3w">  Editor</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_4q1z3w">  EditorFixedMenu</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_4q1z3w">  RichTextKit</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_4q1z3w">  articleToolbar</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">}</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui/editor</span><span class="s_w1p9wo">&#39;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>import … from &#39;frappe-ui&#39;</code></td><td><code>import … from &#39;frappe-ui/editor&#39;</code></td></tr><tr><td><code>&lt;TextEditor&gt;</code></td><td><code>&lt;Editor&gt;</code></td></tr><tr><td><code>:content=&quot;x&quot; @change=&quot;x = $event&quot;</code></td><td><code>v-model=&quot;x&quot;</code> (<code>@change</code> still emitted)</td></tr><tr><td>HTML string only</td><td><code>v-model</code> + <code>format=&quot;json&quot;</code> for a JSON value</td></tr><tr><td><code>:starterkit-options=&quot;{ heading: { levels } }&quot;</code></td><td><code>RichTextKit.configure({ heading: { levels } })</code> in <code>:extensions</code></td></tr><tr><td>auto-loaded extension set (no opt-out)</td><td>explicit <code>:extensions</code> — pick <code>CommentKit</code> / <code>RichTextKit</code> / <code>InlineKit</code></td></tr><tr><td><code>:mentions</code> / <code>:tags</code> props</td><td><code>kit.configure({ mention: { items, component }, tag: { items } })</code></td></tr><tr><td><code>:bubble-menu=&quot;true&quot;</code></td><td><code>&lt;EditorBubbleMenu :items=&quot;articleToolbar&quot;&gt;</code> in the default slot</td></tr><tr><td><code>:floating-menu=&quot;true&quot;</code></td><td><code>&lt;EditorFloatingMenu :items&gt;</code></td></tr><tr><td><code>&lt;TextEditorFixedMenu :buttons&gt;</code></td><td><code>&lt;EditorFixedMenu :items&gt;</code></td></tr><tr><td><code>&lt;TextEditorContent&gt;</code></td><td><code>&lt;EditorContent&gt;</code></td></tr><tr><td>menu <code>:buttons</code></td><td>menu <code>:items</code></td></tr><tr><td>hand-rolled <code>textEditorMenuButtons</code> array</td><td><code>commentToolbar</code> / <code>articleToolbar</code> / <code>minimalToolbar</code> presets</td></tr><tr><td><code>#top</code> / <code>#bottom</code> / <code>#editor</code> slots</td><td>one default slot — you render <code>EditorContent</code> + menus yourself</td></tr><tr><td><code>:uploadFunction</code> (optional, frappe default)</td><td><code>:upload-function</code> (required to enable uploads)</td></tr></tbody></table><h3 id="compose-don-t-configure" tabindex="-1">Compose, don&#39;t configure <a class="header-anchor" href="#compose-don-t-configure" aria-label="Permalink to “Compose, don&#39;t configure”">​</a></h3><p>v0 took every option as a prop on <code>&lt;TextEditor&gt;</code> and auto-loaded every extension. v1 renders no chrome of its own — you place the building blocks inside its default slot and they pick up the editor from context (the <code>:editor</code> prop is only needed when composing primitives without <code>&lt;Editor&gt;</code>):</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1i4ay4"> lang</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">ts</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">ref</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">vue</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_4q1z3w">  Editor</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_4q1z3w">  EditorContent</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_4q1z3w">  EditorBubbleMenu</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_4q1z3w">  RichTextKit</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_4q1z3w">  articleToolbar</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">}</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui/editor</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> content</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> ref</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;&#39;</span><span class="s_13ahmt">)</span></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> extensions</span><span class="s_2ekfrt"> =</span><span class="s_13ahmt"> [</span></span>
<span class="line"><span class="s_22m8k2">  RichTextKit</span><span class="s_1jjt6x">.</span><span class="s_indoxt">configure</span><span class="s_13ahmt">({</span><span class="s_r4oegk"> heading</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> {</span><span class="s_r4oegk"> levels</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> [</span><span class="s_40mev6">2</span><span class="s_1jjt6x">,</span><span class="s_40mev6"> 3</span><span class="s_1jjt6x">,</span><span class="s_40mev6"> 4</span><span class="s_1jjt6x">,</span><span class="s_40mev6"> 5</span><span class="s_1jjt6x">,</span><span class="s_40mev6"> 6</span><span class="s_13ahmt">]</span><span class="s_13ahmt"> }</span><span class="s_13ahmt"> })</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">]</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;</span><span class="s_wac0bt">Editor</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">content</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> :extensions</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">extensions</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> placeholder</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">Write…</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">    &lt;</span><span class="s_wac0bt">EditorBubbleMenu</span><span class="s_1i4ay4"> :items</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">articleToolbar</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">    &lt;</span><span class="s_wac0bt">EditorContent</span><span class="s_1i4ay4"> class</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">prose max-w-none</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;/</span><span class="s_wac0bt">Editor</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p>Pick the kit per surface: <code>CommentKit</code> (light — no table/toc/slash), <code>RichTextKit</code> (full document), <code>InlineKit</code> (single-line). Configure kit members in place rather than via props — e.g. mentions/tags through <code>kit.configure({ mention: {...}, tag: {...} })</code>. To keep the mention/tag nodes rendering but disable the live popups, pass <code>mention: { items: null }</code>.</p><p>For a fully custom layout (e.g. a title <code>&lt;textarea&gt;</code> as a sibling of the body), skip <code>&lt;Editor&gt;</code> and drive <code>useEditor</code> yourself — see <a href="./molecules/editor#composing-primitives">Composing primitives</a> — rendering <code>&lt;EditorContent&gt;</code> and the menus as siblings of your own markup.</p><h3 id="gotchas" tabindex="-1">Gotchas <a class="header-anchor" href="#gotchas" aria-label="Permalink to “Gotchas”">​</a></h3><ul><li><strong>Tailwind must scan frappe-ui&#39;s editor source.</strong> Menu icons are literal <code>lucide-*</code> class strings living in <code>frappe-ui/src/molecules/**</code>. Add that glob to your <code>tailwind.config.js</code> <code>content</code>, or the toolbar / bubble / floating icons silently won&#39;t be generated.</li><li><strong>Uploads need an explicit handler.</strong> v0 silently invoked the Frappe upload; v1 requires <code>:upload-function</code>. In a Frappe app: <code>(file) =&gt; useFileUpload().upload(file, {})</code>.</li><li><strong>TipTap must be v3.</strong> The v1 editor is built on TipTap 3 — pin <code>@tiptap/core</code>, <code>@tiptap/pm</code>, and <code>@tiptap/vue-3</code> to <code>^3</code>.</li></ul><h2 id="family-stylesheets-list-style-css-editor-style-css" tabindex="-1">Family stylesheets (list-style.css / editor-style.css) <a class="header-anchor" href="#family-stylesheets-list-style-css-editor-style-css" aria-label="Permalink to “Family stylesheets (list-style.css / editor-style.css)”">​</a></h2><p>The manual <code>frappe-ui/list-style.css</code> and <code>frappe-ui/editor-style.css</code> exports are removed. The <code>frappe-ui/list</code> and <code>frappe-ui/editor</code> barrels are now marked as side-effectful, so each family&#39;s CSS lands in your production build automatically when you import anything from its subpath.</p><p>Delete the manual imports; there is nothing to add back:</p><div class="language-css"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">/* Before */</span></span>
<span class="line"><span class="s_19y4hp">@</span><span class="s_50ecpt">import</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui/list-style.css</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">;</span></span>
<span class="line"><span class="s_19y4hp">@</span><span class="s_50ecpt">import</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui/editor-style.css</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">;</span></span>
<span class="line"><span class="s_1th9sy">/* After: nothing — the CSS ships with the subpath import */</span></span></code></pre></div><p>The build fails loudly (<code>Missing &quot;./list-style.css&quot; specifier in &quot;frappe-ui&quot; package</code>) until the lines are gone.</p><h2 id="autocomplete-removed" tabindex="-1">Autocomplete (removed) <a class="header-anchor" href="#autocomplete-removed" aria-label="Permalink to “Autocomplete (removed)”">​</a></h2><p><code>Autocomplete</code> is gone in v1. It merged single- and multi-select via the <code>multiple</code> boolean; v1 splits them: <a href="./components/combobox"><code>Combobox</code></a> for single, <a href="./components/multiselect"><code>MultiSelect</code></a> for multiple.</p><p>The import fails, so your build tells you where every call site is. Three things inside those call sites change quietly instead, and each has a before/after below: the <strong>v-model payload</strong>, the <strong>group key</strong>, and the <strong><code>open</code> slot prop</strong>, which was a function and is now a boolean.</p><p>Sweep your codebase:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_euu481">grep</span><span class="s_2d41qv"> -rln</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">&lt;Autocomplete\\b</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4"> src</span><span class="s_2d41qv"> --include=</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">*.vue</span><span class="s_w1p9wo">&#39;</span><span class="s_1th9sy">   # find usages</span></span>
<span class="line"><span class="s_euu481">grep</span><span class="s_2d41qv"> -rln</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">:multiple</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4"> src</span><span class="s_2d41qv"> --include=</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">*.vue</span><span class="s_w1p9wo">&#39;</span><span class="s_1th9sy">         # these become MultiSelect</span></span>
<span class="line"><span class="s_euu481">grep</span><span class="s_2d41qv"> -rn</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">items:</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4"> src</span><span class="s_2d41qv"> --include=</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">*.vue</span><span class="s_w1p9wo">&#39;</span><span class="s_1th9sy">             # grouped options — see below</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Before (<code>Autocomplete</code>)</th><th>After</th></tr></thead><tbody><tr><td><code>:multiple=&quot;false&quot;</code> (default)</td><td>use <code>Combobox</code></td></tr><tr><td><code>:multiple=&quot;true&quot;</code></td><td>use <code>MultiSelect</code></td></tr><tr><td><code>v-model</code> (option or value)</td><td><code>v-model</code> (value / value array)</td></tr><tr><td><code>@change</code></td><td><code>@update:modelValue</code> (<code>@update:selectedOption</code> for the option)</td></tr><tr><td>grouped <code>{ group, items }</code></td><td>grouped <code>{ group, options }</code></td></tr><tr><td><code>placement</code> (string)</td><td><code>side</code> + <code>align</code></td></tr><tr><td><code>:showFooter</code></td><td><code>#footer</code> slot (MultiSelect has built-in)</td></tr><tr><td><code>:bodyClasses</code></td><td><code>data-slot</code> CSS</td></tr><tr><td><code>:maxOptions</code></td><td>no equivalent</td></tr><tr><td><code>#target=&quot;{ togglePopover }&quot;</code></td><td><code>#trigger</code>, with no click handler (<code>open</code> is now a boolean)</td></tr><tr><td><code>#prefix</code> / <code>#suffix</code> / <code>#item-*</code></td><td>same (<code>#suffix</code> now replaces chevron)</td></tr></tbody></table><h3 id="the-v-model-payload-inverts" tabindex="-1">The v-model payload inverts <a class="header-anchor" href="#the-v-model-payload-inverts" aria-label="Permalink to “The v-model payload inverts”">​</a></h3><p><code>Autocomplete</code> took and emitted the <strong>whole option object</strong>; both replacements model the <strong>value only</strong> — <code>Combobox</code> is <code>string | number | null</code>, <code>MultiSelect</code> is <code>(string | number)[]</code>. Code that reads <code>country.value</code> off the model gets <code>undefined</code> rather than a type error, since the model was loosely typed.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Autocomplete</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">country</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">options</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">countries</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> @</span><span class="s_1i4ay4">change</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">onChange</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1th9sy">&lt;!-- country === { label: &#39;India&#39;, value: &#39;in&#39; } --&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Combobox</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">country</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">options</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">countries</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> @</span><span class="s_1i4ay4">update</span><span class="s_1jjt6x">:</span><span class="s_1i4ay4">model-value</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">onChange</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1th9sy">&lt;!-- country === &#39;in&#39; --&gt;</span></span></code></pre></div><p>Still need the whole option — for its <code>description</code>, an id field, anything beyond the value? Listen to <code>@update:selectedOption</code>, which carries it:</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Combobox</span></span>
<span class="line"><span class="s_1i4ay4">  v-model</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">country</span><span class="s_w1p9wo">&quot;</span></span>
<span class="line"><span class="s_1jjt6x">  :</span><span class="s_1i4ay4">options</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">countries</span><span class="s_w1p9wo">&quot;</span></span>
<span class="line"><span class="s_1jjt6x">  @</span><span class="s_1i4ay4">update</span><span class="s_1jjt6x">:</span><span class="s_1i4ay4">selected-option</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">(</span><span class="s_fsg3al">option</span><span class="s_13ahmt">)</span><span class="s_50ecpt"> =&gt;</span><span class="s_13ahmt"> (</span><span class="s_22m8k2">label</span><span class="s_2ekfrt"> =</span><span class="s_22m8k2"> option</span><span class="s_1jjt6x">?.</span><span class="s_11933w">label</span><span class="s_50ecpt"> ??</span><span class="s_w1p9wo"> &#39;&#39;</span><span class="s_13ahmt">)</span><span class="s_w1p9wo">&quot;</span></span>
<span class="line"><span class="s_6am9cx">/&gt;</span></span></code></pre></div><h3 id="grouped-options-items-→-options" tabindex="-1">Grouped options: <code>items</code> → <code>options</code> <a class="header-anchor" href="#grouped-options-items-→-options" aria-label="Permalink to “Grouped options: items → options”">​</a></h3><p>The key holding a group&#39;s children is now <code>options</code>, matching the top-level prop. Both components throw and name the group if they find the old key, so this one is caught the first time the picker opens — but only then, not at build time.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Autocomplete</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">options</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">[{</span><span class="s_r4oegk"> group</span><span class="s_1jjt6x">: </span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">Asia</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">, </span><span class="s_r4oegk">items</span><span class="s_1jjt6x">: </span><span class="s_13ahmt">[</span><span class="s_11933w">india</span><span class="s_1jjt6x">, </span><span class="s_11933w">japan</span><span class="s_13ahmt">]</span><span class="s_13ahmt"> }]</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Combobox</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">options</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_13ahmt">[{</span><span class="s_r4oegk"> group</span><span class="s_1jjt6x">: </span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">Asia</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">, </span><span class="s_r4oegk">options</span><span class="s_1jjt6x">: </span><span class="s_13ahmt">[</span><span class="s_11933w">india</span><span class="s_1jjt6x">, </span><span class="s_11933w">japan</span><span class="s_13ahmt">]</span><span class="s_13ahmt"> }]</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span></code></pre></div><h3 id="target-→-trigger-and-drop-the-click-handler" tabindex="-1"><code>#target</code> → <code>#trigger</code>, and drop the click handler <a class="header-anchor" href="#target-→-trigger-and-drop-the-click-handler" aria-label="Permalink to “#target → #trigger, and drop the click handler”">​</a></h3><p>The slot is renamed, and the wiring inside it changes. <code>Autocomplete</code> handed <code>#target</code> a <code>togglePopover</code> function you had to call yourself. <code>Combobox</code> and <code>MultiSelect</code> attach the open toggle to the <code>#trigger</code> element for you, so the handler is not just unnecessary — a <code>togglePopover()</code> carried through the rename throws <code>togglePopover is not a function</code> on every click. The popover still opens, because the component&#39;s own handler already ran, so this reads as &quot;works, but noisy&quot; until someone looks at the console.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Autocomplete</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">options</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">fields</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #target=&quot;{ togglePopover }&quot;&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;Button label=&quot;Add filter&quot; @click=&quot;togglePopover()&quot; /&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;/template&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Autocomplete</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">Combobox</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">options</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">fields</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #trigger&gt;</span></span>
<span class="line"><span class="s_6am9cx">    &lt;Button label=&quot;Add filter&quot; /&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;/template&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Combobox</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p><strong><code>open</code> changed from a function to a boolean, and that part is silent.</strong> On <code>#target</code> it was the function that opened the popover, so anything reading it as a value — <code>v-if=&quot;open&quot;</code>, <code>:class=&quot;{ &#39;rotate-180&#39;: open }&quot;</code> — was reading a function object and was <strong>always truthy</strong>. On <code>#trigger</code> it is the real open state, so those expressions start doing what they always looked like they did.</p><p><code>#trigger</code> receives <code>{ open, disabled, query, selectedOption, displayValue, clear, setOpen }</code>. Use <code>setOpen</code> for a trigger that has to open the popover from somewhere other than its own click.</p><h3 id="the-default-trigger-is-trigger-button" tabindex="-1">The default trigger is <code>trigger=&quot;button&quot;</code> <a class="header-anchor" href="#the-default-trigger-is-trigger-button" aria-label="Permalink to “The default trigger is trigger=&quot;button&quot;”">​</a></h3><p><code>Autocomplete</code> rendered a button showing the selection, with the search box inside the popover. <code>Combobox</code> defaults to <code>trigger=&quot;input&quot;</code> — the trigger <em>is</em> the search field. Pass <code>trigger=&quot;button&quot;</code> to keep the old shape.</p><h2 id="formcontrol-type-autocomplete-removed" tabindex="-1">FormControl <code>type=&quot;autocomplete&quot;</code> (removed) <a class="header-anchor" href="#formcontrol-type-autocomplete-removed" aria-label="Permalink to “FormControl type=&quot;autocomplete&quot; (removed)”">​</a></h2><p><strong>This one is silent.</strong> <code>FormControl</code> is a dispatcher: with the <code>autocomplete</code> case gone, the type falls through to <code>TextInput</code> and is still forwarded as an html input type. The result is <code>&lt;input type=&quot;autocomplete&quot;&gt;</code>, which every browser renders as a plain text box. No build error, no runtime error — just a picker that turned into a text field. A dev-only <code>console.error</code> names it.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">FormControl</span><span class="s_1i4ay4"> type</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">autocomplete</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">options</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">countries</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">country</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1th9sy">&lt;!-- country === { label: &#39;India&#39;, value: &#39;in&#39; } --&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">FormControl</span><span class="s_1i4ay4"> type</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">combobox</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">options</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">countries</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">country</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"><span class="s_1th9sy">&lt;!-- country === &#39;in&#39; --&gt;</span></span></code></pre></div><p>The v-model payload inverts here too, for the same reason as above. Or use the standalone <a href="./components/combobox"><code>Combobox</code></a>, which exposes the full set of props and slots without the wrapper.</p><h2 id="http-transport-and-the-frappeui-plugin" tabindex="-1">HTTP transport and the <code>FrappeUI</code> plugin <a class="header-anchor" href="#http-transport-and-the-frappeui-plugin" aria-label="Permalink to “HTTP transport and the FrappeUI plugin”">​</a></h2><p>v1 has one HTTP path. <code>frappeRequest</code> is it; <code>call</code> is a thin wrapper over it for the common &quot;POST to a whitelisted method&quot; case. <code>request</code>, <code>createCall</code> and <code>initSocket</code> are gone, and <code>app.use(FrappeUI)</code> is down to a single option.</p><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>import { request }</code></td><td><code>import { frappeRequest }</code></td></tr><tr><td><code>createCall(options)</code></td><td>wrap <code>call</code> yourself, or use <code>frappeRequest</code></td></tr><tr><td><code>import initSocket</code></td><td>your own <code>io(...)</code> connection</td></tr><tr><td><code>app.use(FrappeUI, { config })</code></td><td><code>setConfig(key, value)</code> per entry</td></tr><tr><td><code>app.use(FrappeUI, { call })</code></td><td><code>import { call }</code> where you need it</td></tr><tr><td><code>this.$resources</code> (implicit)</td><td><code>app.use(FrappeUI, { resources: true })</code></td></tr></tbody></table><p>The first three are build failures — your bundler or type-check names them. The rest are the silent ones.</p><h3 id="call-now-honours-setconfig" tabindex="-1"><code>call</code> now honours <code>setConfig</code> <a class="header-anchor" href="#call-now-honours-setconfig" aria-label="Permalink to “call now honours setConfig”">​</a></h3><p><code>call</code> built its own <code>fetch</code> and never read the config, so <code>requestBaseUrl</code> and <code>requestHeaders</code> were quietly ignored on every <code>call()</code> while <code>frappeRequest</code> respected them. That inconsistency is fixed, which means a <code>call</code> in an app that sets either one now behaves differently — usually the way you assumed it already did. Two knock-on effects worth checking:</p><ul><li>If you set <code>requestBaseUrl</code> for local dev against a remote site, <code>call</code> now goes to the remote site too, with <code>credentials: &#39;include&#39;</code>.</li><li>If you set <code>serverMessagesHandler</code>, <code>_server_messages</code> returned by a <code>call</code> now reach it. Previously only <code>frappeRequest</code> and the resources fed it, so expect toasts from paths that used to be silent.</li></ul><p><code>call</code>&#39;s signature, the value it resolves to, and the <code>{ response, status, error }</code> object passed to <code>onError</code> are all unchanged.</p><h3 id="the-plugin-s-config-option-is-gone" tabindex="-1">The plugin&#39;s <code>config</code> option is gone <a class="header-anchor" href="#the-plugin-s-config-option-is-gone" aria-label="Permalink to “The plugin&#39;s config option is gone”">​</a></h3><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">// Before</span></span>
<span class="line"><span class="s_22m8k2">app</span><span class="s_1jjt6x">.</span><span class="s_indoxt">use</span><span class="s_13ahmt">(</span><span class="s_22m8k2">FrappeUI</span><span class="s_1jjt6x">,</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_r4oegk">  config</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_r4oegk">    resourceFetcher</span><span class="s_1jjt6x">:</span><span class="s_22m8k2"> frappeRequest</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">    defaultListUrl</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">gameplan.extends.client.get_list</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">    systemTimezone</span><span class="s_1jjt6x">:</span><span class="s_22m8k2"> window</span><span class="s_1jjt6x">.</span><span class="s_11933w">system_timezone</span><span class="s_50ecpt"> ||</span><span class="s_40mev6"> null</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">  }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">})</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">// After</span></span>
<span class="line"><span class="s_indoxt">setConfig</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">resourceFetcher</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_22m8k2"> frappeRequest</span><span class="s_13ahmt">)</span></span>
<span class="line"><span class="s_indoxt">setConfig</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">defaultListUrl</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">gameplan.extends.client.get_list</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">)</span></span>
<span class="line"><span class="s_indoxt">setConfig</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">systemTimezone</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_22m8k2"> window</span><span class="s_1jjt6x">.</span><span class="s_11933w">system_timezone</span><span class="s_50ecpt"> ||</span><span class="s_40mev6"> null</span><span class="s_13ahmt">)</span></span>
<span class="line"><span class="s_22m8k2">app</span><span class="s_1jjt6x">.</span><span class="s_indoxt">use</span><span class="s_13ahmt">(</span><span class="s_22m8k2">FrappeUI</span><span class="s_13ahmt">)</span></span></code></pre></div><p>Passing a removed option is not a type error if your <code>main.js</code> is plain JS, so the plugin logs a dev-mode warning naming the option it ignored. Note that <code>setConfig</code> only accepts keys of <code>FrappeUIConfig</code> — if you were passing a key that isn&#39;t one, it was never read and can be deleted.</p><h3 id="resources-is-opt-in" tabindex="-1"><code>$resources</code> is opt-in <a class="header-anchor" href="#resources-is-opt-in" aria-label="Permalink to “$resources is opt-in”">​</a></h3><p>The plugin used to install the v1 resources Options API mixin by default, so <code>this.$resources</code>, <code>$getResource</code>, <code>$getDoc</code>, <code>$getListResource</code> and <code>$refetchResource</code> existed in any app that called <code>app.use(FrappeUI)</code>. It now installs only when asked:</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_22m8k2">app</span><span class="s_1jjt6x">.</span><span class="s_indoxt">use</span><span class="s_13ahmt">(</span><span class="s_22m8k2">FrappeUI</span><span class="s_1jjt6x">,</span><span class="s_13ahmt"> {</span><span class="s_r4oegk"> resources</span><span class="s_1jjt6x">:</span><span class="s_40mev6"> true</span><span class="s_13ahmt"> })</span></span></code></pre></div><p>Nothing changes for Composition API code — <code>createResource</code>, <code>createListResource</code> and <code>createDocumentResource</code> never went through the plugin. You need the option only if you declare a <code>resources: { … }</code> block in a component&#39;s options.</p><p>You will not have to work this out from a blank screen. A component that declares <code>resources</code> without the option throws on creation, naming itself and the fix, and reading <code>this.$resources</code> throws too. Both throw in production builds as well as dev — this is a break that has no quiet failure mode.</p><h3 id="initsocket-is-gone" tabindex="-1"><code>initSocket</code> is gone <a class="header-anchor" href="#initsocket-is-gone" aria-label="Permalink to “initSocket is gone”">​</a></h3><p>It was a nine-line <code>io()</code> wrapper, and the plugin created one by default — which meant apps that also built their own socket held two live connections per page load. If you relied on the <code>$socket</code> global the plugin set, create the connection yourself:</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">io</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">socket.io-client</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> host</span><span class="s_2ekfrt"> =</span><span class="s_22m8k2"> window</span><span class="s_1jjt6x">.</span><span class="s_22m8k2">location</span><span class="s_1jjt6x">.</span><span class="s_11933w">hostname</span></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> port</span><span class="s_2ekfrt"> =</span><span class="s_22m8k2"> window</span><span class="s_1jjt6x">.</span><span class="s_22m8k2">location</span><span class="s_1jjt6x">.</span><span class="s_11933w">port</span><span class="s_50ecpt"> ?</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">:9000</span><span class="s_w1p9wo">&#39;</span><span class="s_50ecpt"> :</span><span class="s_w1p9wo"> &#39;&#39;</span></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> protocol</span><span class="s_2ekfrt"> =</span><span class="s_22m8k2"> port</span><span class="s_50ecpt"> ?</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">http</span><span class="s_w1p9wo">&#39;</span><span class="s_50ecpt"> :</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">https</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> siteName</span><span class="s_2ekfrt"> =</span><span class="s_edvzsf"> import</span><span class="s_1jjt6x">.</span><span class="s_1vt12c">meta</span><span class="s_1jjt6x">.</span><span class="s_22m8k2">env</span><span class="s_1jjt6x">.</span><span class="s_40mev6">DEV</span><span class="s_50ecpt"> ?</span><span class="s_22m8k2"> host</span><span class="s_50ecpt"> :</span><span class="s_22m8k2"> window</span><span class="s_1jjt6x">.</span><span class="s_11933w">site_name</span></span>
<span class="line"></span>
<span class="line"><span class="s_22m8k2">app</span><span class="s_1jjt6x">.</span><span class="s_22m8k2">config</span><span class="s_1jjt6x">.</span><span class="s_22m8k2">globalProperties</span><span class="s_1jjt6x">.</span><span class="s_11933w">$socket</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> io</span><span class="s_13ahmt">(</span></span>
<span class="line"><span class="s_w1p9wo">  \`</span><span class="s_20l85h">\${</span><span class="s_22m8k2">protocol</span><span class="s_20l85h">}</span><span class="s_2575z4">://</span><span class="s_20l85h">\${</span><span class="s_22m8k2">host</span><span class="s_20l85h">}\${</span><span class="s_22m8k2">port</span><span class="s_20l85h">}</span><span class="s_2575z4">/</span><span class="s_20l85h">\${</span><span class="s_22m8k2">siteName</span><span class="s_20l85h">}</span><span class="s_w1p9wo">\`</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">  {</span><span class="s_r4oegk"> withCredentials</span><span class="s_1jjt6x">:</span><span class="s_40mev6"> true</span><span class="s_13ahmt"> }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">)</span></span></code></pre></div><p>Until you do, reading <code>this.$socket</code> throws with that instruction rather than returning <code>undefined</code> and crashing in whatever realtime handler reads it next. Assigning your own replaces the guard. The same applies to <code>$call</code>, the other global the plugin used to install — import <code>call</code> from <code>frappe-ui</code> instead.</p><h2 id="pagemetaplugin-—-removed" tabindex="-1">pageMetaPlugin — removed <a class="header-anchor" href="#pagemetaplugin-—-removed" aria-label="Permalink to “pageMetaPlugin — removed”">​</a></h2><p><code>pageMetaPlugin</code> and the global mixin it installed are gone. A <code>pageMeta()</code> component option still compiles — it&#39;s a plain, unread object key — but nothing calls it anymore, so <code>document.title</code> and the favicon stop updating. This is a <strong>silent break</strong>: no error, no warning, the page just stops retitling itself.</p><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>app.use(pageMetaPlugin)</code></td><td>delete — nothing to install</td></tr><tr><td><code>pageMeta() { return { title, emoji } }</code></td><td><code>usePageMeta(() =&gt; ({ title, emoji }))</code> in <code>setup()</code></td></tr></tbody></table><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">export</span><span class="s_edvzsf"> default</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_indoxt">  pageMeta</span><span class="s_13ahmt">()</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_29n2kq">    return</span><span class="s_13ahmt"> { </span><span class="s_r4oegk">title</span><span class="s_1jjt6x">:</span><span class="s_118ozv"> this</span><span class="s_1jjt6x">.</span><span class="s_11933w">pageTitle</span><span class="s_1jjt6x">,</span><span class="s_r4oegk"> emoji</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">🌈</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> }</span></span>
<span class="line"><span class="s_13ahmt">  }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">}</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">usePageMeta</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_indoxt">usePageMeta</span><span class="s_13ahmt">(()</span><span class="s_50ecpt"> =&gt;</span><span class="s_13ahmt"> ({</span><span class="s_r4oegk"> title</span><span class="s_1jjt6x">:</span><span class="s_22m8k2"> pageTitle</span><span class="s_1jjt6x">.</span><span class="s_11933w">value</span><span class="s_1jjt6x">,</span><span class="s_r4oegk"> emoji</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">🌈</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> }))</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p><code>usePageMeta</code> works the same everywhere — see the <a href="./other/composables#usepagemeta">composables page</a>.</p><h2 id="commandpalette" tabindex="-1">CommandPalette <a class="header-anchor" href="#commandpalette" aria-label="Permalink to “CommandPalette”">​</a></h2><p><code>show</code> is renamed to <code>open</code>, matching the rest of the library&#39;s overlay vocabulary. This is a <strong>silent break</strong>: Vue accepts the unknown <code>show</code> prop with no error, so the palette just never opens.</p><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>v-model:show=&quot;show&quot;</code></td><td><code>v-model:open=&quot;open&quot;</code></td></tr></tbody></table><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">CommandPalette</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">:</span><span class="s_1i4ay4">show</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">show</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">groups</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">groups</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> @</span><span class="s_1i4ay4">select</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">onSelect</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">CommandPalette</span><span class="s_1i4ay4"> v-model</span><span class="s_1jjt6x">:</span><span class="s_1i4ay4">open</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">open</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> :</span><span class="s_1i4ay4">groups</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">groups</span><span class="s_w1p9wo">&quot;</span><span class="s_1jjt6x"> @</span><span class="s_1i4ay4">select</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_22m8k2">onSelect</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2"> /&gt;</span></span></code></pre></div><p><code>Mod+K</code> now opens the palette on its own (registered internally via <code>useShortcut</code>) — delete any app-level keydown listener that toggled it.</p><h2 id="keyboardshortcut" tabindex="-1">KeyboardShortcut <a class="header-anchor" href="#keyboardshortcut" aria-label="Permalink to “KeyboardShortcut”">​</a></h2><p>The deprecated <code>shortcut</code> prop, and the unused <code>meta</code> / <code>ctrl</code> / <code>shift</code> / <code>alt</code> boolean props, are removed. Use <code>combo</code> — a string like <code>&quot;Mod+Shift+K&quot;</code>.</p><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>&lt;KeyboardShortcut shortcut=&quot;Mod+K&quot; /&gt;</code></td><td><code>&lt;KeyboardShortcut combo=&quot;Mod+K&quot; /&gt;</code></td></tr><tr><td><code>&lt;KeyboardShortcut ctrl shift&gt;K&lt;/KeyboardShortcut&gt;</code></td><td><code>&lt;KeyboardShortcut combo=&quot;Mod+Shift+K&quot; /&gt;</code></td></tr></tbody></table><h2 id="pageheadermobile-family-—-slot-names" tabindex="-1">PageHeaderMobile family — slot names <a class="header-anchor" href="#pageheadermobile-family-—-slot-names" aria-label="Permalink to “PageHeaderMobile family — slot names”">​</a></h2><p><code>PageHeaderMobile</code>&#39;s <code>#left</code>/<code>#right</code> and <code>PageHeaderMobileTitle</code>&#39;s <code>#icon</code> are renamed to the shared <code>#prefix</code>/<code>#suffix</code> vocabulary (see <a href="https://github.com/frappe/frappe-ui/blob/main/PHILOSOPHY.md" target="_blank" rel="noreferrer">PHILOSOPHY.md P6</a>). This is a <strong>silent break</strong>: Vue drops content passed to an unknown slot name with no error or warning — the back button, title icon, or trailing action just stops rendering.</p><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>PageHeaderMobile</code> <code>#left</code></td><td><code>#prefix</code></td></tr><tr><td><code>PageHeaderMobile</code> <code>#right</code></td><td><code>#suffix</code></td></tr><tr><td><code>PageHeaderMobileTitle</code> <code>#icon</code></td><td><code>#prefix</code></td></tr></tbody></table><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">&lt;!-- Before --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">PageHeaderMobile</span><span class="s_1i4ay4"> title</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">Space</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #left&gt;&lt;BackButton /&gt;&lt;/template&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #right&gt;&lt;Button icon=&quot;lucide-more-horizontal&quot; /&gt;&lt;/template&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">PageHeaderMobile</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">PageHeaderMobileTitle</span><span class="s_1i4ay4"> title</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">Space</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #icon&gt;&lt;SpaceIcon /&gt;&lt;/template&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">PageHeaderMobileTitle</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">&lt;!-- After --&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">PageHeaderMobile</span><span class="s_1i4ay4"> title</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">Space</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #prefix&gt;&lt;BackButton /&gt;&lt;/template&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #suffix&gt;&lt;Button icon=&quot;lucide-more-horizontal&quot; /&gt;&lt;/template&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">PageHeaderMobile</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">PageHeaderMobileTitle</span><span class="s_1i4ay4"> title</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">Space</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_6am9cx">  &lt;template #prefix&gt;&lt;SpaceIcon /&gt;&lt;/template&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">PageHeaderMobileTitle</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p>Grep for <code>#left</code>, <code>#right</code>, and <code>#icon</code> on these two components specifically — other components (e.g. <code>ListView</code>&#39;s footer) have their own unrelated <code>#left</code>/ <code>#right</code> slots that are unaffected.</p><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to “FAQ”">​</a></h2><p><strong>Will my CSS break?</strong> Where structure changed, components expose <code>data-*</code> hooks (<code>data-slot</code>, <code>data-state</code>, <code>data-size</code>, <code>data-variant</code>). Audit selectors that targeted tags or classes.</p><p><strong>Report bugs:</strong> <a href="https://github.com/frappe/frappe-ui/issues/new" target="_blank" rel="noreferrer">file an issue</a> with the <code>v1-beta</code> label. Include the component name, before/after code, version, and a repro.</p>`,274)])])}const u=a(t,[["render",o]]);export{h as __pageData,u as default};
